insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('month-end-pattern-spotting-sheet', 'Month-End Pattern Spotting Sheet', 'worksheet'::resource_kind, 'A page for scanning the past month to spot what repeated, what helped and what to change.', 'Use it to help a client see patterns across weeks instead of single days.', array['Adults']::text[], '20 minutes', 'Give it near the end of a month and ask the client to look through a calendar or phone for patterns. Notice which days were best and what they had in common. Keep answers short. The client picks one pattern to keep and one to change, and the choice is theirs.', '[{"id": "f0", "type": "textarea", "label": "Days this month that went well and what they had in common"}, {"id": "f1", "type": "textarea", "label": "Days that were hard and what they had in common"}, {"id": "f2", "type": "textarea", "label": "A pattern I noticed that surprised me"}, {"id": "f3", "type": "textarea", "label": "One thing I want to keep doing"}, {"id": "f4", "type": "textarea", "label": "One thing I want to change next month"}]'::jsonb, array['routines', 'review', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('energy-giver-and-drainer-sort', 'Energy Giver and Drainer Sort', 'worksheet'::resource_kind, 'A two-column sort of everyday activities and people into those that add energy and those that take it.', 'Use it to give a client a clearer picture of where their energy goes.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list a typical week''s activities, then sort them together in session. Some items land in both columns, and that is useful to talk about rather than resolve. Look for one drainer that can be shrunk and one giver that can be protected. Frame it as a map the client builds, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "Activities that usually leave me with more energy"}, {"id": "f1", "type": "textarea", "label": "Activities that usually leave me with less energy"}, {"id": "f2", "type": "textarea", "label": "Something that is both a giver and a drainer, and why"}, {"id": "f3", "type": "textarea", "label": "One drainer I could shrink or schedule differently"}, {"id": "f4", "type": "textarea", "label": "One giver I want to protect this week"}]'::jsonb, array['energy', 'self-monitoring', 'habits']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('conversation-prep-planner', 'Conversation Prep Planner', 'worksheet'::resource_kind, 'A planning page for a hard conversation: what to say, when to say it and what to do afterward.', 'Use it to help a client enter a difficult conversation with a plan and a landing spot.', array['Adults', 'Teens']::text[], '20 minutes', 'Use it before a conversation the client is dreading, such as with a boss, relative or friend. Rehearse the opening line aloud in session, since writing it and saying it feel very different. Make sure the client plans for what they will do after, whatever the response. The plan is a draft they can set aside if the moment shifts.', '[{"id": "f0", "type": "textarea", "label": "Who I need to talk to and what I hope will change"}, {"id": "f1", "type": "textarea", "label": "The one thing I most want them to understand"}, {"id": "f2", "type": "textarea", "label": "My opening sentence, written the way I would actually say it"}, {"id": "f3", "type": "textarea", "label": "A reaction I am bracing for, and what I will do if it happens"}, {"id": "f4", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['communication', 'planning', 'assertiveness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('two-minute-start-planner', 'Two-Minute Start Planner', 'worksheet'::resource_kind, 'A planner for shrinking a hard-to-start task into a two-minute first step and choosing when to do it.', 'Use it to help a client get moving on something they keep putting off.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client name a task they avoid and shrink it until the first step takes about two minutes. Pick a cue in the day for starting. Clients often resist making it small enough, so keep shrinking. Review how the start felt, not how much got done, and let the client choose whether to keep going once begun.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The two-minute version of the first step"}, {"id": "f2", "type": "textarea", "label": "The moment in my day when I will start"}, {"id": "f3", "type": "textarea", "label": "What my mind might say to stop me"}, {"id": "f4", "type": "textarea", "label": "What I will do if I get stuck"}]'::jsonb, array['habits', 'routines', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('gratitude-letter-planner', 'Gratitude Letter Planner', 'worksheet'::resource_kind, 'A planning sheet for writing a letter of thanks to someone who made a difference.', 'Use it to help a client put real appreciation into words and decide whether to share it.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to choose someone safe and uncomplicated to thank. Spend the session on the specific details, since specifics are what make a letter land. Sending it is optional, and some clients will want to write it and keep it. Notice any complicated feelings that surface and make room for them.', '[{"id": "f0", "type": "textarea", "label": "Someone who helped me, and what they did"}, {"id": "f1", "type": "textarea", "label": "What changed for me because of it"}, {"id": "f2", "type": "textarea", "label": "A specific moment I still remember"}, {"id": "f3", "type": "textarea", "label": "What I want them to know now"}, {"id": "f4", "type": "textarea", "label": "Whether I want to send, read aloud or keep this letter"}]'::jsonb, array['gratitude', 'connection', 'positive psychology']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('friend-versus-self-voice-comparison', 'Friend Versus Self Voice Comparison', 'cbt'::resource_kind, 'A two-column page comparing the voice a client uses on themselves with the voice they use on a friend.', 'Use it to help a client hear the gap between self-talk and the kindness they give others.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent hard moment and have the client write what they said to themselves, then what they would say to a close friend in the same spot. Let the client notice the gap. Ask what it would take to try the friend voice for a week and which sentence feels most believable.', '[{"id": "f0", "type": "textarea", "label": "A moment I was hard on myself"}, {"id": "f1", "type": "textarea", "label": "What I said to myself"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "What is different between the two"}, {"id": "f4", "type": "textarea", "label": "One friend-voice sentence I will try"}]'::jsonb, array['self-criticism', 'self-talk', 'perspective']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('thought-challenge-role-play-script', 'Thought Challenge Role Play Script', 'cbt'::resource_kind, 'A script for a role play where the therapist voices the client''s thought and the client argues back.', 'Use it to help a client practice answering a thought out loud before doing it alone.', array['Adults', 'Teens']::text[], 'Full session', 'Take the voice of the client''s thought, using their own words, and let the client respond. Start gently and raise the intensity only as the client stays steady. Swap roles for a round so the client hears you answer the thought. Afterward ask which responses felt true rather than merely clever.', '[{"id": "f0", "type": "textarea", "label": "The thought I want to practice answering"}, {"id": "f1", "type": "textarea", "label": "The words I would use if this thought said it out loud"}, {"id": "f2", "type": "textarea", "label": "My best answer, in my own words"}, {"id": "f3", "type": "textarea", "label": "What felt weak or unconvincing in my answer"}, {"id": "f4", "type": "textarea", "label": "A stronger answer I could use next time"}]'::jsonb, array['thought challenging', 'role play', 'core CBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('cognitive-rehearsal-imagery-plan', 'Cognitive Rehearsal Imagery Plan', 'cbt'::resource_kind, 'A plan for picturing a coming situation step by step, including coping well with the hard moments.', 'Use it to help a client mentally rehearse a challenge before facing it.', array['Adults']::text[], '25 minutes', 'Walk the client through a calm, slow rehearsal of an upcoming event, pausing at each hard point to add a coping step. Keep the image realistic rather than perfect. If imagery stirs up more distress than it helps, stop and ground, then try a written version instead. Practice twice in session before suggesting home use.', '[{"id": "f0", "type": "textarea", "label": "The situation I want to rehearse"}, {"id": "f1", "type": "textarea", "label": "The first few things I will see and hear"}, {"id": "f2", "type": "textarea", "label": "The hardest moment, and what I will do in it"}, {"id": "f3", "type": "textarea", "label": "Something I will say to myself at that point"}, {"id": "f4", "type": "textarea", "label": "How I will wrap up and take care of myself after"}]'::jsonb, array['imagery', 'rehearsal', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('advantages-and-disadvantages-of-worrying-sheet', 'Advantages and Disadvantages of Worrying Sheet', 'cbt'::resource_kind, 'A two-sided sheet for listing what worrying seems to do for a client and what it costs them.', 'Use it to open up the beliefs that keep worry going.', array['Adults']::text[], '20 minutes', 'Ask the client to be honest about the ways worry feels useful, such as being prepared or showing care, before listing costs. Taking the advantages seriously matters, since clients often defend worry when it is dismissed. Then ask whether each advantage could be had another way. The client decides what, if anything, to try differently.', '[{"id": "f0", "type": "textarea", "label": "What worrying seems to do for me"}, {"id": "f1", "type": "textarea", "label": "What worrying costs me in time, energy or relationships"}, {"id": "f2", "type": "textarea", "label": "A time worry really did help me"}, {"id": "f3", "type": "textarea", "label": "A time worry did not help at all"}, {"id": "f4", "type": "textarea", "label": "Another way I could get the same benefit"}]'::jsonb, array['worry', 'beliefs about worry', 'pros and cons']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('behavioral-prediction-rating-sheet', 'Behavioral Prediction Rating Sheet', 'cbt'::resource_kind, 'A before-and-after rating page for comparing what a client expects with what actually happens.', 'Use it to turn a client''s predictions into something they can check.', array['Adults', 'Teens']::text[], 'Five minutes before and after a task', 'Have the client rate how likely and how bad they expect something to be before an activity, then rate what happened after. Keep the task small and specific so the comparison is clear. If the prediction was right, that is useful information too. Review the gap together and let the client draw their own conclusions.', '[{"id": "f0", "type": "textarea", "label": "The activity I am about to try"}, {"id": "f1", "type": "textarea", "label": "What I expect will happen"}, {"id": "f2", "type": "textarea", "label": "How likely I think it is, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I make of the difference between the two"}]'::jsonb, array['behavioral experiment', 'predictions', 'monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('thought-bubble-distance-drawing', 'Thought Bubble Distance Drawing', 'act'::resource_kind, 'A drawing exercise placing a hard thought in bubbles at different distances from the client.', 'Use it to give a client a visual sense of space between themselves and a thought.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client draw themselves in the middle of a page and write a hard thought in a bubble pressed against them, then redraw it farther away and smaller. Talk about what changes and what stays. The aim is flexibility, not making the thought go away. Offer it as an experiment.', '[{"id": "f0", "type": "textarea", "label": "The thought I drew in a bubble"}, {"id": "f1", "type": "textarea", "label": "What it was like with the bubble right up against me"}, {"id": "f2", "type": "textarea", "label": "What changed when I drew it farther away"}, {"id": "f3", "type": "textarea", "label": "What I could do with the thought at that distance"}, {"id": "f4", "type": "textarea", "label": "A moment this week I could try this"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('goal-behind-the-goal-ladder', 'Goal Behind the Goal Ladder', 'act'::resource_kind, 'A ladder that climbs from a stated goal to the value underneath it and back to a step available today.', 'Use it to help a client find a doable value-based step beneath a stalled goal.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with a goal the client has stalled on and ask why it matters, then why that matters, until a value appears. Then climb back down to a small step available today. Take your time. Their own wording is the best guide, and some goals may turn out to be less important than they seemed.', '[{"id": "f0", "type": "textarea", "label": "A goal I have stalled on"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "Why that matters, one step further"}, {"id": "f3", "type": "textarea", "label": "The value underneath it all"}, {"id": "f4", "type": "textarea", "label": "A step I can take today toward that value"}]'::jsonb, array['values', 'goal setting', 'clarification']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('noticing-the-story-sheet', 'Noticing the Story Sheet', 'act'::resource_kind, 'A sheet for naming a familiar life story and noticing how it shapes what a client does.', 'Use it to help a client see a story as a story while still taking it seriously.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to give a recurring story a short title, like The Story of Not Good Enough, and write what it says. Treat the story with respect since it came from real experience. Then ask what the story asks them to do and not do. The aim is flexibility, not proving the story false.', '[{"id": "f0", "type": "textarea", "label": "The title I would give this story"}, {"id": "f1", "type": "textarea", "label": "What the story tells me about myself"}, {"id": "f2", "type": "textarea", "label": "What the story pushes me to do or avoid"}, {"id": "f3", "type": "textarea", "label": "What it costs me when I follow it every time"}, {"id": "f4", "type": "textarea", "label": "What I could do that fits my values while the story is present"}]'::jsonb, array['defusion', 'narrative', 'core ACT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('compassionate-observer-walk', 'Compassionate Observer Walk', 'act'::resource_kind, 'A guided walk where a client practices noticing thoughts and feelings from a steady, kind vantage point.', 'Use it to build a perspective that can hold hard experience without being swept away.', array['Adults']::text[], '15 minutes', 'Walk outside with the client, or move around the room, and invite them to narrate what they notice in the surroundings, then in the body, then in thoughts. Keep your own voice slow and warm. Afterward ask what it was like to be the one noticing. Offer it as an experiment and let the client decide how useful it feels.', '[{"id": "f0", "type": "textarea", "label": "Something I noticed around me on the walk"}, {"id": "f1", "type": "textarea", "label": "Something I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "A thought I noticed passing through"}, {"id": "f3", "type": "textarea", "label": "What it felt like to watch rather than to be pulled along"}, {"id": "f4", "type": "textarea", "label": "A place this week I could practice noticing"}]'::jsonb, array['self-as-context', 'mindfulness', 'self-compassion']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('workable-or-not-daily-check', 'Workable or Not Daily Check', 'act'::resource_kind, 'A daily sticky check of whether what a client did moved them toward or away from what matters.', 'Use it to build a habit of asking whether an action is working for the person they want to be.', array['Adults']::text[], 'Five minutes daily', 'Give the client one or two actions to watch each day rather than the whole day. Frame answers as information and not as grades. Look together for patterns across the week, especially the moves that feel good short term but lead somewhere they do not want to go. Choose one thing to try differently.', '[{"id": "f0", "type": "textarea", "label": "Something I did today"}, {"id": "f1", "type": "textarea", "label": "Whether it moved me toward or away from what matters"}, {"id": "f2", "type": "textarea", "label": "What I was trying to feel or avoid when I did it"}, {"id": "f3", "type": "textarea", "label": "What else I could have done that fits what matters"}, {"id": "f4", "type": "textarea", "label": "What I want to try tomorrow"}]'::jsonb, array['workability', 'committed action', 'monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-coping-statements', 'Radical Acceptance Coping Statements', 'dbt'::resource_kind, 'A page for writing statements a client can say to themselves when fighting what cannot be changed.', 'Use it to help a client prepare words for moments when they are stuck in the fight with reality.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to name something they cannot change right now and write a few statements in their own voice, such as "It is what it is right now." Practice saying them aloud together. Acceptance is not approval, so make that distinction clear. Revise statements that sound hollow.', '[{"id": "f0", "type": "textarea", "label": "Something I cannot change right now"}, {"id": "f1", "type": "textarea", "label": "How I have been fighting it"}, {"id": "f2", "type": "textarea", "label": "A statement that feels true and usable"}, {"id": "f3", "type": "textarea", "label": "A body cue that tells me I am fighting reality"}, {"id": "f4", "type": "textarea", "label": "What I want to do with my energy instead"}]'::jsonb, array['radical acceptance', 'self-talk', 'acceptance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('name-it-to-tame-it-log', 'Name It to Tame It Log', 'dbt'::resource_kind, 'A log for putting precise words on an emotion in the moment and noting what happens to its intensity.', 'Use it to build the habit of labeling emotions as a way to steady them.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'Show the client how to go beyond mad, sad or fine by using a wider feelings list. Ask them to rate intensity before and after naming it. Not every feeling shifts, and that is fine to report. Review the log and look at which situations bring up which emotions.', '[{"id": "f0", "type": "textarea", "label": "What was happening"}, {"id": "f1", "type": "textarea", "label": "The word that best fits what I felt"}, {"id": "f2", "type": "textarea", "label": "How strong it was before naming it, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "How strong it was after naming it"}, {"id": "f4", "type": "textarea", "label": "What I needed in that moment"}]'::jsonb, array['emotion regulation', 'emotion identification', 'skills']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('self-validation-journal-page', 'Self-Validation Journal Page', 'dbt'::resource_kind, 'A journal page for finding what makes sense about a client''s own reaction without judging it.', 'Use it to practice treating one''s own feelings as understandable.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the client to look for why a reaction makes sense given the situation and their history, without agreeing it was the best choice. Model the language aloud. Clients who are used to judging themselves may find this awkward at first, so keep the bar low and the examples small.', '[{"id": "f0", "type": "textarea", "label": "What happened and how I reacted"}, {"id": "f1", "type": "textarea", "label": "How I judged myself for it"}, {"id": "f2", "type": "textarea", "label": "Why my reaction makes sense given what I know"}, {"id": "f3", "type": "textarea", "label": "What I would say to someone I care about in my place"}, {"id": "f4", "type": "textarea", "label": "What I need now"}]'::jsonb, array['validation', 'self-compassion', 'regulation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('describe-skill-practice-sheet', 'Describe Skill Practice Sheet', 'dbt'::resource_kind, 'A practice sheet for describing a situation using only facts, without opinions or guesses.', 'Use it to separate what happened from what a client made of it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to describe a recent event as a camera would see it, and then list their interpretations separately. Gently flag opinion words that slip into the facts. The exercise often lowers intensity just by slowing things down. Practice on a neutral event first.', '[{"id": "f0", "type": "textarea", "label": "The event, described only with facts"}, {"id": "f1", "type": "textarea", "label": "The interpretations and opinions I added"}, {"id": "f2", "type": "textarea", "label": "How I felt when I read the facts alone"}, {"id": "f3", "type": "textarea", "label": "How I felt when I read my interpretations"}, {"id": "f4", "type": "textarea", "label": "What I will do with this difference next time"}]'::jsonb, array['mindfulness', 'core DBT', 'skills']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('one-mindfully-single-task-log', 'One-Mindfully Single-Task Log', 'dbt'::resource_kind, 'A daily log for doing one ordinary activity with full attention and noting what pulls attention away.', 'Use it to build the skill of doing one thing at a time.', array['Adults', 'Teens']::text[], 'Ten minutes daily', 'Pick one routine activity, such as washing dishes or walking, and ask the client to give it complete attention for a few minutes. Normalize a wandering mind, and treat each return as the practice. Ask what pulled their attention and what it was like to come back.', '[{"id": "f0", "type": "textarea", "label": "The one activity I chose today"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my senses"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How I brought it back"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['mindfulness', 'attention', 'core DBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('weekly-gratitude-turn-toward-log', 'Weekly Gratitude Turn-Toward Log', 'couples'::resource_kind, 'A shared log where each partner notes the small ways the other turned toward them this week.', 'Use it to help a couple notice and name the connection already happening.', array['Couples']::text[], '10 minutes', 'Both partners keep their own list during the week and read them aloud in session or at home. Look for specific, small moments rather than grand gestures. Watch for a partner who dismisses their own list, and invite them to try again. Each partner owns their own part.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something my partner did that helped me feel close"}, {"id": "f1", "type": "textarea", "label": "Partner B: something my partner did that helped me feel close"}, {"id": "f2", "type": "textarea", "label": "Partner A: a small moment I almost missed"}, {"id": "f3", "type": "textarea", "label": "Partner B: a small moment I almost missed"}, {"id": "f4", "type": "textarea", "label": "Together: one thing we want to do more of next week"}]'::jsonb, array['Gottman', 'gratitude', 'connection']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('shared-calendar-planning-guide', 'Shared Calendar Planning Guide', 'couples'::resource_kind, 'A guide for a couple to plan the coming week together so the load, time and downtime feel fair.', 'Use it to help partners coordinate time without it becoming an argument.', array['Couples']::text[], '30 minutes', 'Have partners fill in their own commitments first, then talk through the overlaps. Look for how each partner wants to protect time with each other and alone time. Try this in session once before sending it home. Both partners should leave with something they asked for and something they agreed to.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the commitments I have this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: the commitments I have this week"}, {"id": "f2", "type": "textarea", "label": "Where our time overlaps or collides"}, {"id": "f3", "type": "textarea", "label": "Partner A: time I want protected for myself"}, {"id": "f4", "type": "textarea", "label": "Partner B: time I want protected for myself"}, {"id": "f5", "type": "textarea", "label": "Time we will set aside for just the two of us"}]'::jsonb, array['planning', 'routines', 'communication']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('conflict-cool-down-signal-cards', 'Conflict Cool-Down Signal Cards', 'couples'::resource_kind, 'Two cards each partner can raise to ask for a pause, with an agreed plan for how to return to the topic.', 'Use it to give a couple a simple, agreed way to pause a heated moment.', array['Couples']::text[], '20 minutes', 'Have the couple agree on the signal, the length of the pause and who restarts the conversation, before they need it. Practice once on a mild topic. Remind them that the pause is for settling the body, not for rehearsing arguments. Each partner commits to coming back.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the signal I will use and what it means"}, {"id": "f1", "type": "textarea", "label": "Partner B: the signal I will use and what it means"}, {"id": "f2", "type": "textarea", "label": "How long we will pause before we try again"}, {"id": "f3", "type": "textarea", "label": "Partner A: what helps me settle during a pause"}, {"id": "f4", "type": "textarea", "label": "Partner B: what helps me settle during a pause"}, {"id": "f5", "type": "textarea", "label": "Who will start the conversation again, and how"}]'::jsonb, array['de-escalation', 'conflict', 'regulation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('couple-strengths-mapping-sheet', 'Couple Strengths Mapping Sheet', 'couples'::resource_kind, 'A joint sheet where partners list what each of them does well and what they do well as a team.', 'Use it to build on what is already working in a relationship.', array['Couples']::text[], '25 minutes', 'Ask each partner to list the strengths they see in the other before their own. Notice who finds it hard to receive praise. End by naming one team strength they can draw on in a current difficulty. Keep the tone concrete and specific.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three strengths I see in my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: three strengths I see in my partner"}, {"id": "f2", "type": "textarea", "label": "Something we do well together"}, {"id": "f3", "type": "textarea", "label": "A time we handled something hard well"}, {"id": "f4", "type": "textarea", "label": "How we can use that strength on what we are facing now"}]'::jsonb, array['strengths', 'connection', 'Gottman']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('date-night-rebuilding-planner', 'Date Night Rebuilding Planner', 'couples'::resource_kind, 'A planner for choosing, scheduling and debriefing a low-pressure time together.', 'Use it to help partners restart shared time that has slipped away.', array['Couples']::text[], '20 minutes', 'Keep it small and doable. Each partner suggests options, and the couple picks one that both agree to. Debrief together afterward on what was enjoyable and what to change. Avoid using the date to solve problems; the goal is time together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I would enjoy doing together"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I would enjoy doing together"}, {"id": "f2", "type": "textarea", "label": "The one we picked and when it will happen"}, {"id": "f3", "type": "textarea", "label": "What we will do about phones and distractions"}, {"id": "f4", "type": "textarea", "label": "After: what we liked and what we would change"}]'::jsonb, array['connection', 'planning', 'intimacy']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('kindness-tree-craft', 'Kindness Tree Craft', 'kids'::resource_kind, 'A child makes a paper tree and adds a leaf each time they notice or do something kind.', 'Use it to help a child notice and enjoy kindness over days and weeks.', array['Children']::text[], '30 minutes', 'The child draws or builds a tree and decorates leaves to stick on over the week. The parent helps by pointing out kind moments, noticing out loud and writing a few words on each leaf for younger children. The tree stays somewhere visible at home. Keep it about noticing, not about winning.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "Who I want to be kind to next"}, {"id": "f4", "type": "textarea", "label": "What I will draw on my next leaf"}]'::jsonb, array['kindness', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('calm-glitter-jar-activity', 'Calm Glitter Jar Activity', 'kids'::resource_kind, 'A child shakes a jar of glitter and watches it settle as a picture of a mind calming down.', 'Use it to give a child a visual they can use when feelings are swirling.', array['Children']::text[], '20 minutes', 'Build the jar together with water, glue and glitter, then shake it and watch it settle while breathing slowly. The parent practices alongside the child and offers it later as an invitation, never as a punishment. Explain that the glitter is like thoughts and feelings that settle when given time.', '[{"id": "f0", "type": "textarea", "label": "What my glitter looked like when I shook it"}, {"id": "f1", "type": "textarea", "label": "What it looked like after it settled"}, {"id": "f2", "type": "textarea", "label": "A time I feel shaken up like the glitter"}, {"id": "f3", "type": "textarea", "label": "What I can do while I wait to settle"}, {"id": "f4", "type": "textarea", "label": "Where we will keep the jar"}]'::jsonb, array['self-soothing', 'children', 'regulation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('feelings-faces-paper-plate-craft', 'Feelings Faces Paper Plate Craft', 'kids'::resource_kind, 'A child decorates paper plates as faces showing different feelings and talks about when each one shows up.', 'Use it to help a child connect feeling words with faces and real situations.', array['Children']::text[], '30 minutes', 'Make several plates with different feelings, using yarn, markers and stickers. The parent joins in and shares a time they felt one of the feelings. Use the finished plates for guessing games at home. Ask open questions, and let the child decide which feelings to make.', '[{"id": "f0", "type": "textarea", "label": "The feeling I made first"}, {"id": "f1", "type": "textarea", "label": "What the face looks like"}, {"id": "f2", "type": "textarea", "label": "A time I felt this feeling"}, {"id": "f3", "type": "textarea", "label": "What my body feels like when I feel it"}, {"id": "f4", "type": "textarea", "label": "What helps me when I have this feeling"}]'::jsonb, array['emotion identification', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('courage-badge-design', 'Courage Badge Design', 'kids'::resource_kind, 'A child designs a badge for a brave thing they did and a plan for the next one.', 'Use it to help a child recognize and celebrate small acts of courage.', array['Children']::text[], '25 minutes', 'The child draws the badge, names the brave thing and decides where to wear or display it. The parent adds a line about what they saw. Keep the focus on effort and trying, rather than results. A repeat badge for each new brave step works well.', '[{"id": "f0", "type": "textarea", "label": "The brave thing I did"}, {"id": "f1", "type": "textarea", "label": "What the badge looks like"}, {"id": "f2", "type": "textarea", "label": "Who saw me do it"}, {"id": "f3", "type": "textarea", "label": "How I felt before and after"}, {"id": "f4", "type": "textarea", "label": "The next brave thing I might try"}]'::jsonb, array['strengths', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('gratitude-paper-chain', 'Gratitude Paper Chain', 'kids'::resource_kind, 'A child writes or draws something they are thankful for on each link of a paper chain that grows across a week.', 'Use it to give a child a daily habit of noticing good things.', array['Children']::text[], '20 minutes', 'Cut strips of colorful paper and add a link each day. The parent adds links of their own and reads the chain aloud at the end of the week. Younger children draw rather than write. Hang the chain where the family can see it grow.', '[{"id": "f0", "type": "textarea", "label": "Something I am thankful for today"}, {"id": "f1", "type": "textarea", "label": "Someone who made me smile"}, {"id": "f2", "type": "textarea", "label": "Something I like about my home"}, {"id": "f3", "type": "textarea", "label": "Something I did that I liked"}, {"id": "f4", "type": "textarea", "label": "What I will add to the chain tomorrow"}]'::jsonb, array['gratitude', 'children', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('silent-line-up-feelings-game', 'Silent Line-Up Feelings Game', 'game'::resource_kind, 'A silent group game where players line up by the strength of a feeling and then compare notes.', 'Use it to help a group see that people experience the same situation at different intensities.', array['Groups']::text[], '20 minutes', 'Name a situation, like getting a surprise, and have players line up without speaking from least to most intense. Players take turns saying where they stood and why. There are no wrong places. In the debrief ask what surprised them and what they learned about each other.', '[{"id": "f0", "type": "textarea", "label": "The situation we lined up for"}, {"id": "f1", "type": "textarea", "label": "Where I stood and why"}, {"id": "f2", "type": "textarea", "label": "Where someone else stood that surprised me"}, {"id": "f3", "type": "textarea", "label": "What I learned about how people react differently"}, {"id": "f4", "type": "textarea", "label": "A feeling I would like to line up for next time"}]'::jsonb, array['group', 'emotion identification', 'communication']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('coping-skill-pictionary', 'Coping Skill Pictionary', 'game'::resource_kind, 'A drawing game where players sketch a coping skill and teammates guess it, followed by talking about when they use it.', 'Use it to make coping skills memorable and fun to review.', array['Groups']::text[], '25 minutes', 'Divide into two teams and give each a stack of skill cards. A player draws the skill without words or letters while teammates guess. After a correct guess, the drawer shares one time the skill might help. Keep score lightly and end on the debrief.', '[{"id": "f0", "type": "textarea", "label": "The skill I drew or guessed"}, {"id": "f1", "type": "textarea", "label": "A time I could use it"}, {"id": "f2", "type": "textarea", "label": "A skill I forgot I had"}, {"id": "f3", "type": "textarea", "label": "A skill I would like to try this week"}, {"id": "f4", "type": "textarea", "label": "What I will tell someone about today"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('value-stories-dice-game', 'Value Stories Dice Game', 'game'::resource_kind, 'Players roll dice to pick a value and tell a short true story about living by it.', 'Use it to help players connect everyday moments to what matters to them.', array['Groups']::text[], '30 minutes', 'Make a value card for each number on the die. Players roll, read the value and tell a short true story. Others can ask one question. Passing is allowed, and some players will prefer a one-sentence answer. In the debrief ask what values showed up most.', '[{"id": "f0", "type": "textarea", "label": "The value I rolled"}, {"id": "f1", "type": "textarea", "label": "A short story of living it"}, {"id": "f2", "type": "textarea", "label": "A time I found it hard to live it"}, {"id": "f3", "type": "textarea", "label": "Someone who showed me this value"}, {"id": "f4", "type": "textarea", "label": "One small way I will use it this week"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('perspective-swap-cards', 'Perspective Swap Cards', 'game'::resource_kind, 'Players draw cards with everyday scenarios and describe them as another person in it might see them.', 'Use it to practice seeing the same event from more than one angle.', array['Groups']::text[], '25 minutes', 'Write scenarios on cards, like a late text reply or a canceled plan. A player draws one and tells it first from their own view and then from another''s. The group adds a third view. Keep the scenarios low stakes, and avoid real conflicts among members.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "How I saw it"}, {"id": "f2", "type": "textarea", "label": "How someone else might have seen it"}, {"id": "f3", "type": "textarea", "label": "A third view the group added"}, {"id": "f4", "type": "textarea", "label": "What I will remember about this"}]'::jsonb, array['perspective', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('strength-spotting-charades', 'Strength Spotting Charades', 'game'::resource_kind, 'A charades game where players act out a strength and the group guesses and names a time it showed up.', 'Use it to help a group name strengths out loud in a light, active way.', array['Groups']::text[], '25 minutes', 'Place strength words on cards, such as patient, curious, brave. A player acts one out, and the group guesses. Then each person names a time they used it. Offer a pass for anyone who is shy. Close by asking what the group noticed.', '[{"id": "f0", "type": "textarea", "label": "The strength I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "A time I used it"}, {"id": "f2", "type": "textarea", "label": "A strength I saw in someone else today"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use more"}, {"id": "f4", "type": "textarea", "label": "One way I will do that this week"}]'::jsonb, array['strengths', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('safe-now-orientation-sheet', 'Safe Now Orientation Sheet', 'worksheet'::resource_kind, 'A page for noticing where the client is, what year it is and what is safe in the room right now.', 'Use it to give a client a quick, steadying way to orient to the present.', array['Adults']::text[], '10 minutes', 'Practice it in session when the client is calm so it is familiar before it is needed. Keep prompts to the present moment only and never ask for details of past events. If the client becomes more activated, slow down, return to the room together and shorten the exercise.', '[{"id": "f0", "type": "textarea", "label": "Where I am right now"}, {"id": "f1", "type": "textarea", "label": "What today''s date is"}, {"id": "f2", "type": "textarea", "label": "Three things I can see that tell me I am here"}, {"id": "f3", "type": "textarea", "label": "One thing in this room that is safe or comforting"}, {"id": "f4", "type": "textarea", "label": "How my body feels right now"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('helpful-thought-practice-for-reminders', 'Helpful Thought Practice for Reminders', 'cbt'::resource_kind, 'A card for pairing a common reminder reaction with a steadier thought that fits the present.', 'Use it to help a client practice present-focused thoughts when something reminds them of the past.', array['Adults']::text[], '20 minutes', 'Work from the present only: ask what the reminder is and what is true now, without exploring the original event. Write the steadier thought together, in the client''s words. Some clients prefer it spoken rather than written. Go at their pace and stop if it increases distress.', '[{"id": "f0", "type": "textarea", "label": "A reminder that has been catching me off guard"}, {"id": "f1", "type": "textarea", "label": "What my mind tells me when it happens"}, {"id": "f2", "type": "textarea", "label": "What is true about right now"}, {"id": "f3", "type": "textarea", "label": "A steadier thought I can use"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to if it gets hard"}]'::jsonb, array['PTSD and trauma', 'self-talk', 'core CBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('trauma-aware-values-check-in', 'Trauma-Aware Values Check-In', 'act'::resource_kind, 'A gentle values check-in that focuses on what a client wants more of in life now.', 'Use it to keep the future in view alongside the work of feeling safer.', array['Adults']::text[], '20 minutes', 'Keep the questions about the present and the future, and never about the past. Let the client choose the pace and the domains. Small values-based steps, like a short walk with a friend, count. Check in on how the client is feeling after the exercise.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me now"}, {"id": "f1", "type": "textarea", "label": "A small way I can show up for it this week"}, {"id": "f2", "type": "textarea", "label": "What makes that harder right now"}, {"id": "f3", "type": "textarea", "label": "Who can support me with it"}, {"id": "f4", "type": "textarea", "label": "How I will know I did it"}]'::jsonb, array['PTSD and trauma', 'values', 'core ACT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('sleep-settling-skills-plan', 'Sleep Settling Skills Plan', 'dbt'::resource_kind, 'A plan of skills a client can use at bedtime and during night waking to settle and feel safer.', 'Use it to give a client a ready set of steps for hard nights.', array['Adults']::text[], '20 minutes', 'Build the plan in session when the client is rested if possible. Include grounding, paced breathing, a safe-room check and a self-soothe menu. Keep it short enough to remember in the dark. Review what worked after a week and adjust. Nothing on the sheet asks the client to revisit any events.', '[{"id": "f0", "type": "textarea", "label": "What makes bedtime hard for me"}, {"id": "f1", "type": "textarea", "label": "Things in my room I can do to feel safer"}, {"id": "f2", "type": "textarea", "label": "A grounding step I can use when I wake up"}, {"id": "f3", "type": "textarea", "label": "A self-soothing step I like"}, {"id": "f4", "type": "textarea", "label": "Who I can contact in the morning if the night is rough"}]'::jsonb, array['PTSD and trauma', 'sleep', 'distress tolerance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('grounding-category-game', 'Grounding Category Game', 'game'::resource_kind, 'A group game of naming items in a category, such as blue things in the room, to practice shifting attention to the present.', 'Use it to practice grounding in a light, low-pressure way.', array['Groups']::text[], '15 minutes', 'Pick a simple category and go around the circle, each person naming something in the room. Move to harder categories as comfort grows. Keep the tone playful and let people pass. In the debrief ask what the shift felt like. This is a skill practice and not an exploration of anyone''s history.', '[{"id": "f0", "type": "textarea", "label": "The category we used"}, {"id": "f1", "type": "textarea", "label": "Something I named"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body as I played"}, {"id": "f3", "type": "textarea", "label": "A place I could use this outside the group"}, {"id": "f4", "type": "textarea", "label": "Another category I would like to try"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('worry-time-sorting-sheet', 'Worry Time Sorting Sheet', 'worksheet'::resource_kind, 'A sheet for sorting worries into those with a next step and those that can only be noticed.', 'Use it to help a client decide what to act on and what to let be.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to list a day''s worries, then sort them together. Some will have a clear next step, and others are what-ifs that cannot be solved today. Do not talk the client out of any worry. The point is choosing where to put attention.', '[{"id": "f0", "type": "textarea", "label": "Worries on my mind today"}, {"id": "f1", "type": "textarea", "label": "Ones I can do something about"}, {"id": "f2", "type": "textarea", "label": "The next small step for one of them"}, {"id": "f3", "type": "textarea", "label": "Ones I cannot solve today"}, {"id": "f4", "type": "textarea", "label": "What I will do with attention for the rest of the day"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('avoidance-cost-and-benefit-chart', 'Avoidance Cost and Benefit Chart', 'cbt'::resource_kind, 'A chart for weighing what avoiding something gives a client in the short run against what it costs in the long run.', 'Use it to bring both sides of avoidance into view.', array['Adults', 'Teens']::text[], '20 minutes', 'Take the short-term relief seriously, since that is what keeps avoidance going. Then list what it takes from the client''s life over time. The chart tends to motivate better when the client writes their own costs. Choose one small step from it together.', '[{"id": "f0", "type": "textarea", "label": "Something I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "What I get from avoiding it"}, {"id": "f2", "type": "textarea", "label": "What it costs me over time"}, {"id": "f3", "type": "textarea", "label": "What I would be doing if it were not in the way"}, {"id": "f4", "type": "textarea", "label": "One small step I could take toward it"}]'::jsonb, array['anxiety', 'avoidance', 'pros and cons']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anxiety-passenger-seat-practice', 'Anxiety Passenger Seat Practice', 'act'::resource_kind, 'A metaphor practice where anxiety rides along while the client drives toward something that matters.', 'Use it to help a client act on values with anxiety present.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to picture driving to a place that matters with anxiety in the passenger seat. It may comment loudly but does not take the wheel. Draw out what the client would do. Check in afterward on how the image felt and adapt if the metaphor does not fit.', '[{"id": "f0", "type": "textarea", "label": "Where I want to be heading"}, {"id": "f1", "type": "textarea", "label": "What my anxiety says from the passenger seat"}, {"id": "f2", "type": "textarea", "label": "What I do when it grabs the wheel"}, {"id": "f3", "type": "textarea", "label": "What it looks like to keep driving anyway"}, {"id": "f4", "type": "textarea", "label": "One small trip I will take this week"}]'::jsonb, array['anxiety', 'acceptance', 'values']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anxiety-surge-skills-card', 'Anxiety Surge Skills Card', 'dbt'::resource_kind, 'A wallet card listing a few skills a client can use during a surge of anxiety.', 'Use it to give a client a short, personal list for hard moments.', array['Adults', 'Teens']::text[], '15 minutes', 'Make the card with the client in session, choosing three to five skills they have already tried and liked. Rehearse reading and using it. Keep wording concrete and short, such as cold water or counting breaths. Review after a week and swap out what did not help.', '[{"id": "f0", "type": "textarea", "label": "The first skill I will try"}, {"id": "f1", "type": "textarea", "label": "The second skill I will try"}, {"id": "f2", "type": "textarea", "label": "A skill using my body or senses"}, {"id": "f3", "type": "textarea", "label": "A kind thing I will say to myself"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to"}]'::jsonb, array['anxiety', 'distress tolerance', 'skills']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('partner-anxiety-support-plan', 'Partner Anxiety Support Plan', 'couples'::resource_kind, 'A plan where partners agree on how to help when one is anxious, and what not to do.', 'Use it to help partners support each other without feeding avoidance.', array['Couples']::text[], '25 minutes', 'Each partner describes what helps and what makes it worse. Watch for reassurance cycles and name them kindly. Agree on how the helping partner can offer support without taking over. The anxious partner has the final say on what they want to try.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me most when I feel anxious"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do now when my partner is anxious"}, {"id": "f2", "type": "textarea", "label": "Something that does not help, said kindly"}, {"id": "f3", "type": "textarea", "label": "What we will try instead"}, {"id": "f4", "type": "textarea", "label": "How we will check in after"}]'::jsonb, array['anxiety', 'support', 'relationship issues']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('pleasant-activity-menu-planner', 'Pleasant Activity Menu Planner', 'worksheet'::resource_kind, 'A menu of small, doable activities sorted by effort level for days with low energy.', 'Use it to make starting easier by having options ready.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the menu in session with the client, from effortless to bigger. Make sure there are options for the worst days. Ask the client to choose one before leaving. A menu that is too ambitious will be set aside, so keep checking effort ratings.', '[{"id": "f0", "type": "textarea", "label": "Activities that take almost no effort"}, {"id": "f1", "type": "textarea", "label": "Activities that take a little effort"}, {"id": "f2", "type": "textarea", "label": "Activities that take a lot of effort"}, {"id": "f3", "type": "textarea", "label": "One I will try in the next day"}, {"id": "f4", "type": "textarea", "label": "What might get in the way and what I will do"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('hopeless-thought-check-sheet', 'Hopeless Thought Check Sheet', 'cbt'::resource_kind, 'A thought record adapted for hopeless thoughts, with a space to look at what is still unknown.', 'Use it to help a client examine hopeless predictions without dismissing them.', array['Adults', 'Teens']::text[], '20 minutes', 'Take hopeless thoughts seriously and ask about what the client knows and does not know. If the client expresses thoughts of ending their life, stop the worksheet and follow your risk procedures, and remind them they can call or text 988 at any time. Complete this in session rather than as homework.', '[{"id": "f0", "type": "textarea", "label": "The hopeless thought"}, {"id": "f1", "type": "textarea", "label": "What makes it feel true"}, {"id": "f2", "type": "textarea", "label": "What I do not know for sure"}, {"id": "f3", "type": "textarea", "label": "Something that has surprised me before"}, {"id": "f4", "type": "textarea", "label": "If I want to talk to someone right now, I can call or text 988. Who else can I reach out to?"}]'::jsonb, array['depression', 'thinking traps', 'thought record']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('values-in-small-steps-practice', 'Values in Small Steps Practice', 'act'::resource_kind, 'A practice for finding a very small action tied to a value, even when motivation is low.', 'Use it to help a client take values-based steps without waiting to feel like it.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a value and ask what the smallest version of acting on it looks like. Make the step so small that failing is unlikely. Motivation often follows action, so frame it as an experiment. Debrief gently if it did not happen and shrink it further.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "The smallest action I can imagine on it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it"}, {"id": "f3", "type": "textarea", "label": "What my mind might say to talk me out of it"}, {"id": "f4", "type": "textarea", "label": "What I will say back"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('mood-weather-drawing-journal', 'Mood Weather Drawing Journal', 'kids'::resource_kind, 'A child draws the weather that matches their mood each day, with a few words about what happened.', 'Use it to give a child a simple way to show how they feel.', array['Children']::text[], '15 minutes daily', 'The child draws sun, clouds or rain each evening, and the parent sits with them and listens without fixing. Bring the journal to session so the clinician can see the pattern. If you see persistent withdrawal or talk of hurting themselves, follow your clinical judgment and let the parent know to call or text 988 in an emergency.', '[{"id": "f0", "type": "textarea", "label": "The weather of my day today"}, {"id": "f1", "type": "textarea", "label": "What happened that matches it"}, {"id": "f2", "type": "textarea", "label": "Something that made it a little brighter"}, {"id": "f3", "type": "textarea", "label": "Something that made it cloudier"}, {"id": "f4", "type": "textarea", "label": "What I would like to happen tomorrow"}]'::jsonb, array['depression', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('low-battery-day-card-game', 'Low-Battery Day Card Game', 'game'::resource_kind, 'A card game where players draw low-energy days and offer one doable step for each.', 'Use it to practice small steps for hard days.', array['Groups']::text[], '20 minutes', 'Write low-energy situations on cards, such as not wanting to leave bed. Players draw one and suggest one small step, and the group adds ideas. Keep ideas realistic and kind. Debrief by asking which steps felt doable and which felt too large.', '[{"id": "f0", "type": "textarea", "label": "The card I drew"}, {"id": "f1", "type": "textarea", "label": "The small step I suggested"}, {"id": "f2", "type": "textarea", "label": "A step someone else suggested that I liked"}, {"id": "f3", "type": "textarea", "label": "A step that felt too big and how to shrink it"}, {"id": "f4", "type": "textarea", "label": "One I will try this week"}]'::jsonb, array['depression', 'behavioral activation', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('priority-triage-sheet', 'Priority Triage Sheet', 'worksheet'::resource_kind, 'A sheet for sorting a pile of tasks into do now, do soon, delegate and drop.', 'Use it to cut an overwhelming list down to a few next moves.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write every task without sorting first. Then sort together, asking what happens if each one waits. Aim for no more than three things in the do-now column. Clients often put everything in the top bucket, so use questions rather than telling them.', '[{"id": "f0", "type": "textarea", "label": "Everything on my mind to do"}, {"id": "f1", "type": "textarea", "label": "What must be done today"}, {"id": "f2", "type": "textarea", "label": "What can wait a few days"}, {"id": "f3", "type": "textarea", "label": "What someone else could do"}, {"id": "f4", "type": "textarea", "label": "What I could drop or let go"}]'::jsonb, array['ADHD', 'prioritization', 'executive function']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('distraction-parking-lot-log', 'Distraction Parking Lot Log', 'cbt'::resource_kind, 'A log for jotting down distracting thoughts and urges so a client can return to the task.', 'Use it to help a client capture distractions without acting on them.', array['Adults', 'Teens']::text[], 'Ten minutes daily', 'Teach the client to keep a notepad nearby and write each distracting idea in a word or two, then go back. Review what kinds of ideas show up and when. Many clients are surprised by how often the same ones appear. The idea is capture, not suppression.', '[{"id": "f0", "type": "textarea", "label": "The task I was working on"}, {"id": "f1", "type": "textarea", "label": "The distraction that popped up"}, {"id": "f2", "type": "textarea", "label": "What I wrote down"}, {"id": "f3", "type": "textarea", "label": "What I did to get back"}, {"id": "f4", "type": "textarea", "label": "What I noticed about when distractions come"}]'::jsonb, array['ADHD', 'attention', 'self-monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('interest-and-values-bridge', 'Interest and Values Bridge', 'act'::resource_kind, 'A sheet for linking a boring but important task to a value so it gets a little more meaning.', 'Use it to help a client find purpose in tasks that do not hold attention.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a task the client keeps putting off and trace it to something they care about. Pair it with something enjoyable such as music. This does not make the task fun, but it can make starting less of a fight. Check in on what worked.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "Why it matters even though it is dull"}, {"id": "f2", "type": "textarea", "label": "What I care about that it connects to"}, {"id": "f3", "type": "textarea", "label": "Something that could make it a bit easier"}, {"id": "f4", "type": "textarea", "label": "When I will start and for how long"}]'::jsonb, array['ADHD', 'values', 'motivation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('interrupting-urge-delay-card', 'Interrupting Urge Delay Card', 'dbt'::resource_kind, 'A card with a short delay routine for the urge to cut in, blurt or jump ahead in conversation.', 'Use it to build a short gap before a client speaks or acts on a sudden urge.', array['Adults', 'Teens']::text[], '15 minutes', 'Name a typical moment, such as cutting in during a meeting, and make a delay routine with the client: hold the thought, jot a key word, wait for a breath. Rehearse in a role play with a low-stakes topic. Expect it to take practice. Celebrate every use, even when the moment still went sideways, and adjust the wording to fit how the client talks.', '[{"id": "f0", "type": "textarea", "label": "A moment when I blurt or cut in"}, {"id": "f1", "type": "textarea", "label": "What I feel in my body just before"}, {"id": "f2", "type": "textarea", "label": "The key word I will jot down instead"}, {"id": "f3", "type": "textarea", "label": "How long I will wait before speaking"}, {"id": "f4", "type": "textarea", "label": "What I will say when it is my turn"}]'::jsonb, array['ADHD', 'impulsivity', 'distress tolerance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('household-management-split-sheet', 'Household Management Split Sheet', 'couples'::resource_kind, 'A sheet for dividing household tasks between partners in a way that fits each person''s strengths.', 'Use it to help a couple share the load without resentment.', array['Couples']::text[], '30 minutes', 'Have each partner list tasks they do and tasks they find hard. Divide by strengths and not by fairness alone. Include a system for reminders that does not depend on one partner nagging. Review in a few weeks and adjust. Keep a tone of problem solving.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I do well"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I do well"}, {"id": "f2", "type": "textarea", "label": "Tasks that are hard for each of us"}, {"id": "f3", "type": "textarea", "label": "How we will split them"}, {"id": "f4", "type": "textarea", "label": "How we will remind each other without nagging"}]'::jsonb, array['ADHD', 'relationship issues', 'couples']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('morning-routine-picture-chart', 'Morning Routine Picture Chart', 'kids'::resource_kind, 'A child and parent make a picture chart of morning steps the child can follow and check off.', 'Use it to help a child follow a routine without constant reminders.', array['Children']::text[], '30 minutes', 'The child draws or picks pictures for each step, and the parent places the chart where the child will see it. The parent practices cheering on progress and avoids nagging. Keep the chart short, and change it when the child masters a step.', '[{"id": "f0", "type": "textarea", "label": "Steps in my morning"}, {"id": "f1", "type": "textarea", "label": "Which step is hardest for me"}, {"id": "f2", "type": "textarea", "label": "A picture I picked for each step"}, {"id": "f3", "type": "textarea", "label": "What I do when I get stuck"}, {"id": "f4", "type": "textarea", "label": "How my parent can help without nagging"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('urge-wave-tracker', 'Urge Wave Tracker', 'worksheet'::resource_kind, 'A daily tracker of when urges for substance use rise, how strong they get and how long they last.', 'Use it to help a client see urges as events that rise and pass.', array['Adults']::text[], 'Ten minutes daily', 'Show the client how to rate intensity at a few points across an urge. Many clients are surprised that urges peak and fall. Use patterns to plan ahead for the riskiest times. Record, do not judge, and treat every entry as useful information.', '[{"id": "f0", "type": "textarea", "label": "When the urge started"}, {"id": "f1", "type": "textarea", "label": "What was going on"}, {"id": "f2", "type": "textarea", "label": "How strong it got, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "How long until it eased"}]'::jsonb, array['addiction', 'urges', 'monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('substance-use-triggers-chain', 'Substance Use Triggers Chain', 'cbt'::resource_kind, 'A chain from a trigger through thoughts, feelings and actions, with places to break the chain.', 'Use it to help a client find points where a different choice is possible.', array['Adults']::text[], '25 minutes', 'Walk through a recent event step by step, without shaming. Note the links where an alternative could have fit. Ask which link feels easiest to change first. Keep the focus on the pattern and what the client wants to do next time.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "The thought that followed"}, {"id": "f2", "type": "textarea", "label": "The feeling in my body"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "A link where I could have chosen differently"}]'::jsonb, array['addiction', 'triggers', 'chain analysis']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('values-and-substance-use-honest-check', 'Values and Substance Use Honest Check', 'act'::resource_kind, 'A conversation sheet for looking at how substance use fits with what matters to the client.', 'Use it to support a client''s own reflection on what they want.', array['Adults']::text[], '25 minutes', 'Ask the client to name what matters and how substance use has affected it, without pushing a direction. The client is the expert on their life. Ambivalence is normal, so make room for both sides. Follow up on whichever step the client decides to try.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me"}, {"id": "f1", "type": "textarea", "label": "How substance use has fit with that"}, {"id": "f2", "type": "textarea", "label": "How it has gotten in the way"}, {"id": "f3", "type": "textarea", "label": "What I want more of"}, {"id": "f4", "type": "textarea", "label": "One step I am willing to take"}]'::jsonb, array['addiction', 'values', 'workability']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('support-without-control-sheet', 'Support Without Control Sheet', 'couples'::resource_kind, 'A sheet where partners talk about how to support someone changing substance use without policing them.', 'Use it to help partners find a helpful role.', array['Couples']::text[], '30 minutes', 'Each partner shares what they need. The partner using substances says what support feels like and what feels controlling. The supporting partner names their own worries and limits. Agree on one thing each will try. Encourage the supporting partner to have their own support too.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what support looks like to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I worry about"}, {"id": "f2", "type": "textarea", "label": "What feels controlling or unhelpful"}, {"id": "f3", "type": "textarea", "label": "What I need for myself"}, {"id": "f4", "type": "textarea", "label": "One thing we will each try this week"}]'::jsonb, array['addiction', 'relationship issues', 'support']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('say-no-scenario-cards', 'Say No Scenario Cards', 'game'::resource_kind, 'Scenario cards for practicing out loud how to say no when offered substance use.', 'Use it to build a group''s comfort with declining an offer in real time.', array['Groups']::text[], '30 minutes', 'Players draw a scenario, such as an offer at a party, and practice a reply with a partner. Share which phrasing felt natural. Keep scenes light, and let anyone opt out of a scene. In the debrief ask which reply they would actually use and who they could call afterward.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What felt natural or awkward"}, {"id": "f3", "type": "textarea", "label": "A reply I could use next time"}, {"id": "f4", "type": "textarea", "label": "Who I could call afterward"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anger-ladder-rating-sheet', 'Anger Ladder Rating Sheet', 'worksheet'::resource_kind, 'A ladder for rating anger from mild to intense and noting what happens at each rung.', 'Use it to help a client spot anger earlier.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client label steps on the ladder from annoyed to furious and note body cues and urges at each. Spend time on the lower rungs, where choices are easiest. Ask what they can do at each level. Use it to plan which rung to act on.', '[{"id": "f0", "type": "textarea", "label": "What annoyed looks and feels like for me"}, {"id": "f1", "type": "textarea", "label": "What angry looks like"}, {"id": "f2", "type": "textarea", "label": "What furious looks like"}, {"id": "f3", "type": "textarea", "label": "The rung where I still have the most choice"}, {"id": "f4", "type": "textarea", "label": "What I will do when I notice that rung"}]'::jsonb, array['anger management', 'monitoring', 'regulation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('hot-thoughts-in-anger-sheet', 'Hot Thoughts in Anger Sheet', 'cbt'::resource_kind, 'A thought record for the thoughts that fuel anger, with space for other ways to read the situation.', 'Use it to help a client find options between trigger and reaction.', array['Adults', 'Teens']::text[], '20 minutes', 'Look at the thought that came right before the anger. Check for mind reading, shoulds and blaming. Offer the question what else could be going on. The client decides which reading fits. This is not about talking them out of anger.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The thought that flashed in my mind"}, {"id": "f2", "type": "textarea", "label": "How angry I felt, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Another way I could read it"}, {"id": "f4", "type": "textarea", "label": "How angry I feel now"}]'::jsonb, array['anger management', 'thinking traps', 'thought record']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anger-and-what-it-protects-practice', 'Anger and What It Protects Practice', 'act'::resource_kind, 'A practice for noticing what a client cares about underneath their anger.', 'Use it to link anger to values and choose actions that fit.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what the anger is protecting, such as respect or fairness, and what action would serve that. Make room for the feeling without needing it to disappear. Choose one action that fits what the client wants to stand for.', '[{"id": "f0", "type": "textarea", "label": "A recent time I felt angry"}, {"id": "f1", "type": "textarea", "label": "What I care about that felt threatened"}, {"id": "f2", "type": "textarea", "label": "What the anger wanted me to do"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What a values-based response could look like"}]'::jsonb, array['anger management', 'values', 'acceptance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anger-cool-down-tipp-plan', 'Anger Cool-Down TIPP Plan', 'dbt'::resource_kind, 'A plan that adapts TIPP skills for the moments anger spikes.', 'Use it to give a client body-based ways to bring intensity down.', array['Adults', 'Teens']::text[], '20 minutes', 'Check with the client that cold water, paced breathing and movement are safe for them before including them. Practice in session when calm. Write a plan in order of steps. Encourage them to use it early on the ladder and not at the top.', '[{"id": "f0", "type": "textarea", "label": "My early warning sign"}, {"id": "f1", "type": "textarea", "label": "The first body skill I will try"}, {"id": "f2", "type": "textarea", "label": "The second skill"}, {"id": "f3", "type": "textarea", "label": "Where I will go to take a pause"}, {"id": "f4", "type": "textarea", "label": "What I will do once I feel steadier"}]'::jsonb, array['anger management', 'TIPP', 'distress tolerance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anger-stop-sign-craft', 'Anger Stop Sign Craft', 'kids'::resource_kind, 'A child makes a stop sign with steps for what to do when anger shows up.', 'Use it to give a child a visual reminder to pause.', array['Children']::text[], '30 minutes', 'The child decorates a stop sign and writes or draws three steps, such as stop, breathe and choose. The parent practices at home by modeling the steps when they feel upset themselves. Praise when the child uses a step, however small.', '[{"id": "f0", "type": "textarea", "label": "What my body feels like when I am angry"}, {"id": "f1", "type": "textarea", "label": "Step one on my stop sign"}, {"id": "f2", "type": "textarea", "label": "Step two on my stop sign"}, {"id": "f3", "type": "textarea", "label": "Step three on my stop sign"}, {"id": "f4", "type": "textarea", "label": "Where we will hang it"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-normalizing-sheet', 'Intrusive Thought Normalizing Sheet', 'worksheet'::resource_kind, 'A sheet that helps a client see that unwanted thoughts are common and do not define them.', 'Use it to open the conversation about thoughts that feel shameful or scary.', array['Adults', 'Teens']::text[], '20 minutes', 'Go slowly and let the client share only what they are comfortable with. Normalizing helps when it is done respectfully and in the client''s own words. Avoid giving reassurance on the content. Focus on how the client responds to the thought.', '[{"id": "f0", "type": "textarea", "label": "A type of thought that bothers me"}, {"id": "f1", "type": "textarea", "label": "How I feel when it appears"}, {"id": "f2", "type": "textarea", "label": "What I do to make it stop"}, {"id": "f3", "type": "textarea", "label": "What I notice happens after I do that"}, {"id": "f4", "type": "textarea", "label": "How I would like to respond instead"}]'::jsonb, array['OCD', 'intrusive thoughts', 'psychoeducation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('compulsion-substitution-plan', 'Compulsion Substitution Plan', 'cbt'::resource_kind, 'A plan for the steps a client will take as they gradually reduce a compulsion.', 'Use it to build a graded plan for reducing rituals at the client''s pace.', array['Adults', 'Teens']::text[], '25 minutes', 'Plan collaboratively and let the client set the pace. List the ritual, a small change, and what to do when the urge to complete it arrives. Prepare for the surge of anxiety and talk about how it rises and falls. Review after each practice.', '[{"id": "f0", "type": "textarea", "label": "The ritual I want to change"}, {"id": "f1", "type": "textarea", "label": "A small change I will try first"}, {"id": "f2", "type": "textarea", "label": "What I will do with the urge"}, {"id": "f3", "type": "textarea", "label": "What I expect to feel"}, {"id": "f4", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['OCD', 'response prevention', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('uncertainty-is-part-of-life-practice', 'Uncertainty Is Part of Life Practice', 'act'::resource_kind, 'A practice for acting on values while leaving questions about certainty open.', 'Use it to help a client make room for not knowing.', array['Adults', 'Teens']::text[], '20 minutes', 'Give examples of everyday uncertainty the client already lives with. Practice saying maybe, maybe not, and acting anyway. Never provide certainty about what the client fears. Link steps to something the client wants in life.', '[{"id": "f0", "type": "textarea", "label": "A question I keep seeking certainty about"}, {"id": "f1", "type": "textarea", "label": "What I do to try to be sure"}, {"id": "f2", "type": "textarea", "label": "What that costs me"}, {"id": "f3", "type": "textarea", "label": "What I would do if I allowed it to stay uncertain"}, {"id": "f4", "type": "textarea", "label": "One small step I will try"}]'::jsonb, array['OCD', 'uncertainty', 'acceptance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('partner-response-plan-for-rituals', 'Partner Response Plan for Rituals', 'couples'::resource_kind, 'A plan for how a partner responds when the client asks for reassurance or help with a ritual.', 'Use it to reduce accommodation while keeping warmth.', array['Couples']::text[], '25 minutes', 'Agree on kind, short responses together, such as I care about you and I think you can handle this. Practice them aloud. The partner learns to say it without anger. The client can say what support feels like. Adjust together as it goes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I usually respond to requests"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I would like my partner to respond"}, {"id": "f2", "type": "textarea", "label": "A short phrase we will use"}, {"id": "f3", "type": "textarea", "label": "What the partner will do instead"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['OCD', 'couples', 'family accommodation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('worry-wizard-story-craft', 'Worry Wizard Story Craft', 'kids'::resource_kind, 'A child draws and names a worry character and decides how to talk back to it.', 'Use it to help a child separate from worries that boss them around.', array['Children']::text[], '30 minutes', 'The child draws the worry wizard and writes what it says. The parent practices not answering its requests and cheers on the child''s responses. Avoid giving reassurance, and use a warm, steady tone instead. Review in session how it went.', '[{"id": "f0", "type": "textarea", "label": "What the worry wizard looks like"}, {"id": "f1", "type": "textarea", "label": "What it says to me"}, {"id": "f2", "type": "textarea", "label": "What it wants me to do"}, {"id": "f3", "type": "textarea", "label": "What I can say back"}, {"id": "f4", "type": "textarea", "label": "How my parent can help me"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('doubt-dodgeball-debrief-game', 'Doubt Dodgeball Debrief Game', 'game'::resource_kind, 'A soft-ball game where each throw is a doubt and the catcher answers with a maybe, then a debrief.', 'Use it to practice responding to doubts without chasing certainty.', array['Groups']::text[], '25 minutes', 'Players toss a soft ball, say a mild doubt and the catcher responds with maybe and keeps going. Keep doubts low stakes. Afterward discuss how it felt to leave a doubt unanswered. Participants may pass at any time.', '[{"id": "f0", "type": "textarea", "label": "The doubt I threw"}, {"id": "f1", "type": "textarea", "label": "How the maybe response felt"}, {"id": "f2", "type": "textarea", "label": "A time I chase certainty"}, {"id": "f3", "type": "textarea", "label": "What I could do instead"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['OCD', 'uncertainty', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('panic-wave-rating-sheet', 'Panic Wave Rating Sheet', 'worksheet'::resource_kind, 'A sheet for rating a panic wave as it rises, peaks and falls.', 'Use it to show a client that the intensity moves and passes.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client rate intensity every minute during a wave, either in the moment or from memory. Plot it together on a graph. Many clients are surprised by how short the peak is. Respect that panic feels very real, and avoid dismissing it.', '[{"id": "f0", "type": "textarea", "label": "When it started and where I was"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "My highest rating"}, {"id": "f3", "type": "textarea", "label": "How long until it eased"}, {"id": "f4", "type": "textarea", "label": "What I make of the pattern"}]'::jsonb, array['panic attacks', 'monitoring', 'psychoeducation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('safe-place-exposure-plan', 'Safe-Place Exposure Plan', 'cbt'::resource_kind, 'A plan for gradually returning to places or activities a client has avoided since panic.', 'Use it to build gradual, client-led steps back into avoided places.', array['Adults']::text[], '25 minutes', 'List places in order from easiest to hardest and choose a first step the client is confident about. Plan what to do if panic arrives, which is to stay and let it pass. Discuss how success is staying, not feeling calm. Review after each step.', '[{"id": "f0", "type": "textarea", "label": "Places I avoid because of panic"}, {"id": "f1", "type": "textarea", "label": "The easiest one to try first"}, {"id": "f2", "type": "textarea", "label": "What I will do if panic comes"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself"}, {"id": "f4", "type": "textarea", "label": "How I will review it"}]'::jsonb, array['panic attacks', 'exposure', 'avoidance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('making-room-for-racing-hearts-practice', 'Making Room for Racing Hearts Practice', 'act'::resource_kind, 'A practice for allowing fast heartbeat and other sensations while continuing something that matters.', 'Use it to help a client carry sensations with them.', array['Adults']::text[], '20 minutes', 'Ask the client to notice sensations with curiosity, give them a name and breathe around them. Try during a brief task. Check with the client about any medical concerns first. Review what changed in their relationship with the sensation.', '[{"id": "f0", "type": "textarea", "label": "A sensation I try hardest to get rid of"}, {"id": "f1", "type": "textarea", "label": "What I do to push it away"}, {"id": "f2", "type": "textarea", "label": "What it might be like to let it be"}, {"id": "f3", "type": "textarea", "label": "A thing I want to do even with it present"}, {"id": "f4", "type": "textarea", "label": "How the practice went"}]'::jsonb, array['panic attacks', 'acceptance', 'willingness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('panic-self-soothe-menu', 'Panic Self-Soothe Menu', 'dbt'::resource_kind, 'A menu of soothing skills across the senses for use during or after a wave of panic.', 'Use it to give a client choices to try when panic comes.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client choose options for each sense, such as a cold drink or a calming scent. Test a couple in session. Keep the menu where it can be reached fast. After a week review what helped and what to swap.', '[{"id": "f0", "type": "textarea", "label": "A sight that calms me"}, {"id": "f1", "type": "textarea", "label": "A sound that calms me"}, {"id": "f2", "type": "textarea", "label": "A touch or temperature that helps"}, {"id": "f3", "type": "textarea", "label": "A taste or smell that settles me"}, {"id": "f4", "type": "textarea", "label": "What I will reach for first"}]'::jsonb, array['panic attacks', 'self-soothing', 'skills']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('panic-pals-feelings-craft', 'Panic Pals Feelings Craft', 'kids'::resource_kind, 'A child makes a small pal toy that helps them breathe slowly when their body feels very scared.', 'Use it to give a child a friend to breathe with during big body feelings.', array['Children']::text[], '30 minutes', 'The child decorates a small stuffed animal or paper figure and practices breathing with it on their belly. The parent practices alongside and watches for medical concerns that need a doctor. Keep sessions playful, not tense.', '[{"id": "f0", "type": "textarea", "label": "My pal''s name"}, {"id": "f1", "type": "textarea", "label": "What my body feels like when I get very scared"}, {"id": "f2", "type": "textarea", "label": "How my pal helps me breathe"}, {"id": "f3", "type": "textarea", "label": "Where I keep my pal"}, {"id": "f4", "type": "textarea", "label": "Who I can ask for help"}]'::jsonb, array['panic attacks', 'children', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('family-rules-and-routines-map', 'Family Rules and Routines Map', 'worksheet'::resource_kind, 'A map of a family''s key routines and expectations, written so all caregivers can see them.', 'Use it to give caregivers a shared picture of how the household works.', array['Adults']::text[], '30 minutes', 'Have the caregiver list the few routines that matter most and the expected steps. Keep it short, since long lists are hard to follow. Use positive wording, such as walk in the house. Review after a few weeks to see what is working.', '[{"id": "f0", "type": "textarea", "label": "The routines that matter most to us"}, {"id": "f1", "type": "textarea", "label": "What I expect to happen in each"}, {"id": "f2", "type": "textarea", "label": "Where we all get stuck"}, {"id": "f3", "type": "textarea", "label": "One change I will try"}, {"id": "f4", "type": "textarea", "label": "How I will let my child know"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('parent-mind-reading-check', 'Parent Mind-Reading Check', 'cbt'::resource_kind, 'A sheet for catching guesses about why a child acted a certain way and checking other explanations.', 'Use it to help a parent slow down and consider other reasons for a child''s behavior.', array['Adults']::text[], '20 minutes', 'Ask the parent to recall a tough moment and write what they assumed the child meant. Then brainstorm other explanations, such as tiredness, hunger or a skill not yet learned. Keep it compassionate toward the parent, who is usually tired. The parent decides which explanation fits, and which response to try next time.', '[{"id": "f0", "type": "textarea", "label": "What my child did"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant"}, {"id": "f2", "type": "textarea", "label": "How I felt and what I did"}, {"id": "f3", "type": "textarea", "label": "Other reasons my child may have acted that way"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('parenting-by-values-reflection', 'Parenting by Values Reflection', 'act'::resource_kind, 'A reflection on the kind of parent a client wants to be and small actions that fit.', 'Use it to move from guilt toward chosen action.', array['Adults']::text[], '25 minutes', 'Ask what the parent wants their child to remember about them. Link small, doable actions to that. Allow for imperfect days. Notice self-judgment and ask what it asks of them.', '[{"id": "f0", "type": "textarea", "label": "What I want my child to feel around me"}, {"id": "f1", "type": "textarea", "label": "A recent moment that fit that"}, {"id": "f2", "type": "textarea", "label": "A moment that did not"}, {"id": "f3", "type": "textarea", "label": "A small action for this week"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when I fall short"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('parent-validation-practice', 'Parent Validation Practice', 'dbt'::resource_kind, 'A practice for validating a child''s feelings before setting a limit.', 'Use it to help a parent connect before correcting.', array['Adults']::text[], '20 minutes', 'Teach a short sequence: name the feeling, show you get it, then hold the limit. Role play with hard examples. Clarify that validating is not agreeing. Practice with a child at low stakes first. Review what changed.', '[{"id": "f0", "type": "textarea", "label": "A situation where my child was upset"}, {"id": "f1", "type": "textarea", "label": "What I said first"}, {"id": "f2", "type": "textarea", "label": "A validating sentence I could use"}, {"id": "f3", "type": "textarea", "label": "The limit I still need to hold"}, {"id": "f4", "type": "textarea", "label": "How my child responded"}]'::jsonb, array['parenting', 'validation', 'interpersonal effectiveness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('calm-parent-corner-craft', 'Calm Parent Corner Craft', 'kids'::resource_kind, 'A parent and child build a calm corner with tools they pick together.', 'Use it to create a shared, no-punishment space for settling.', array['Children']::text[], '30 minutes', 'The child picks items such as pillows, drawing supplies and a glitter jar. The parent explains it is a place to calm down and not a punishment, and joins in at times. Practice using it when everyone is calm before it is needed.', '[{"id": "f0", "type": "textarea", "label": "What I want in my calm corner"}, {"id": "f1", "type": "textarea", "label": "How it helps my body"}, {"id": "f2", "type": "textarea", "label": "When I might use it"}, {"id": "f3", "type": "textarea", "label": "How my parent can join me"}, {"id": "f4", "type": "textarea", "label": "What we will name it"}]'::jsonb, array['parenting', 'children', 'regulation']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('sleep-protection-plan-for-new-parents', 'Sleep Protection Plan for New Parents', 'worksheet'::resource_kind, 'A plan for getting the longest stretch of sleep possible given a baby''s schedule.', 'Use it to help a new parent protect rest within real limits.', array['Adults']::text[], '25 minutes', 'Map the baby''s waking pattern and the sleep stretches available. Look at help from partners or family. Be realistic and kind, since rest may still be broken. Check whether the parent has asked for the help they need.', '[{"id": "f0", "type": "textarea", "label": "When the baby wakes most"}, {"id": "f1", "type": "textarea", "label": "Who can take a shift"}, {"id": "f2", "type": "textarea", "label": "The longest stretch I can protect"}, {"id": "f3", "type": "textarea", "label": "What helps me fall back asleep"}, {"id": "f4", "type": "textarea", "label": "Who I will ask for help"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('new-parent-perfect-standards-audit', 'New Parent Perfect Standards Audit', 'cbt'::resource_kind, 'A thought record for the shoulds a new parent holds, with room for a good enough standard.', 'Use it to ease perfect-parent standards during the first months.', array['Adults']::text[], '20 minutes', 'Look at the should thoughts that weigh on the parent. Ask where each came from and what a friend would say. If a parent describes thoughts of harming themselves or the baby, follow your procedures and let them know they can call or text 988 or reach their doctor. Complete this in session rather than as homework.', '[{"id": "f0", "type": "textarea", "label": "A should thought I carry as a parent"}, {"id": "f1", "type": "textarea", "label": "Where I learned it"}, {"id": "f2", "type": "textarea", "label": "What a good enough day looks like"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend in my place"}, {"id": "f4", "type": "textarea", "label": "If things feel too heavy, I can call or text 988 or contact my doctor"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-criticism']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('adjusting-to-a-new-identity-practice', 'Adjusting to a New Identity Practice', 'act'::resource_kind, 'A practice for holding both the loss and the joy of changing identity after a birth.', 'Use it to help a parent make room for mixed feelings.', array['Adults']::text[], '25 minutes', 'Invite both gratitude and grief. Ask what they miss and what they are growing into. Avoid pushing toward either side. Small steps to stay connected with who they are can follow. Check in on what the client chose.', '[{"id": "f0", "type": "textarea", "label": "Something I miss about my life before"}, {"id": "f1", "type": "textarea", "label": "Something I am growing into"}, {"id": "f2", "type": "textarea", "label": "A mixed feeling I have been carrying"}, {"id": "f3", "type": "textarea", "label": "A small way to stay in touch with myself"}, {"id": "f4", "type": "textarea", "label": "Who understands all this"}]'::jsonb, array['perinatal and postpartum', 'identity', 'values']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('partner-check-in-after-baby', 'Partner Check-In After Baby', 'couples'::resource_kind, 'A weekly check-in guide for partners to talk about feelings and workload after a baby.', 'Use it to keep partners connected through a demanding season.', array['Couples']::text[], '25 minutes', 'Set aside a short time each week with no baby chores. Each partner shares how they are, what they appreciate and what they need. Listen without fixing. Remind them it is okay for the time to be short. Review what each person wants to change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I am really doing"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I am really doing"}, {"id": "f2", "type": "textarea", "label": "Something I appreciate about my partner"}, {"id": "f3", "type": "textarea", "label": "Something I need this week"}, {"id": "f4", "type": "textarea", "label": "What we will do for each other"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('new-parent-support-bingo', 'New Parent Support Bingo', 'game'::resource_kind, 'A bingo card of small supports that new parents can ask for or offer, played in a group.', 'Use it to normalize asking for and receiving help.', array['Groups']::text[], '30 minutes', 'Make squares for things like a hot meal or an hour alone. Parents mark the ones they have received and the ones they would want. Share a few and practice asking out loud. Debrief on what made asking easier or harder.', '[{"id": "f0", "type": "textarea", "label": "A square I would like to ask for"}, {"id": "f1", "type": "textarea", "label": "A square I received and valued"}, {"id": "f2", "type": "textarea", "label": "What gets in the way of asking"}, {"id": "f3", "type": "textarea", "label": "Who I could ask this week"}, {"id": "f4", "type": "textarea", "label": "How I will phrase the request"}]'::jsonb, array['perinatal and postpartum', 'support', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('self-worth-strengths-inventory', 'Self-Worth Strengths Inventory', 'worksheet'::resource_kind, 'An inventory of strengths the client has, with a real example of each.', 'Use it to help a client collect concrete evidence of what they do well.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for examples and not general statements. If the client lists none, ask what close friends would say. Keep a running copy to add to. Notice the effort of receiving praise and give it room.', '[{"id": "f0", "type": "textarea", "label": "A strength I have"}, {"id": "f1", "type": "textarea", "label": "A time it showed up"}, {"id": "f2", "type": "textarea", "label": "A strength someone else noticed in me"}, {"id": "f3", "type": "textarea", "label": "How it helped someone"}, {"id": "f4", "type": "textarea", "label": "A strength I want to build"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('inner-critic-courtroom', 'Inner Critic Courtroom', 'cbt'::resource_kind, 'A role play in which a client puts the inner critic on trial and examines its evidence.', 'Use it to help a client weigh a harsh voice.', array['Adults', 'Teens']::text[], '25 minutes', 'Set up roles for a prosecutor, a defense and a judge, all played by the client with you assisting. Look at the evidence for and against each critical claim. The client delivers the verdict in their own words. Keep it light and let the client set the pace.', '[{"id": "f0", "type": "textarea", "label": "What the critic says"}, {"id": "f1", "type": "textarea", "label": "Its evidence"}, {"id": "f2", "type": "textarea", "label": "The defense''s evidence"}, {"id": "f3", "type": "textarea", "label": "The verdict"}, {"id": "f4", "type": "textarea", "label": "What I will say next time it speaks"}]'::jsonb, array['self-esteem', 'self-criticism', 'thought challenging']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('self-worth-without-conditions-practice', 'Self-Worth Without Conditions Practice', 'act'::resource_kind, 'A practice for noticing conditions placed on self-worth and acting on values anyway.', 'Use it to loosen if-then rules about worth.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what rules the client holds for being okay, such as I must succeed. Look at how well they serve. Practice acting on values without waiting for the rule to be satisfied. Welcome whatever comes up.', '[{"id": "f0", "type": "textarea", "label": "A rule I hold about being worthy"}, {"id": "f1", "type": "textarea", "label": "Where I learned it"}, {"id": "f2", "type": "textarea", "label": "What it costs"}, {"id": "f3", "type": "textarea", "label": "What I would do without the rule"}, {"id": "f4", "type": "textarea", "label": "One step I will take"}]'::jsonb, array['self-esteem', 'acceptance', 'values']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('self-respect-check-in', 'Self-Respect Check-In', 'dbt'::resource_kind, 'A check-in on whether a recent choice fit the client''s values and self-respect.', 'Use it to build choices that leave a client feeling good about themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'Look at a recent interaction and ask what would have helped the client feel proud of how they acted. Role play the response. Keep judgments gentle. The client decides what matters to them.', '[{"id": "f0", "type": "textarea", "label": "A recent interaction"}, {"id": "f1", "type": "textarea", "label": "How I acted"}, {"id": "f2", "type": "textarea", "label": "What I value in how I treat others and myself"}, {"id": "f3", "type": "textarea", "label": "What I could do next time"}, {"id": "f4", "type": "textarea", "label": "How I will remind myself"}]'::jsonb, array['self-esteem', 'self-respect', 'interpersonal effectiveness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('compliment-mirror-circle', 'Compliment Mirror Circle', 'game'::resource_kind, 'A group game in which each person receives specific compliments and practices simply saying thank you.', 'Use it to practice receiving kindness.', array['Groups']::text[], '20 minutes', 'Each person gets a turn to hear a specific compliment from others and say thank you without deflecting. Keep it genuine and not generic. Allow passing. In the debrief ask how it felt to receive.', '[{"id": "f0", "type": "textarea", "label": "A compliment I received"}, {"id": "f1", "type": "textarea", "label": "How hard it was to take in"}, {"id": "f2", "type": "textarea", "label": "What I said back"}, {"id": "f3", "type": "textarea", "label": "A compliment I gave"}, {"id": "f4", "type": "textarea", "label": "What I will remember"}]'::jsonb, array['self-esteem', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('social-energy-planner', 'Social Energy Planner', 'worksheet'::resource_kind, 'A planner for scheduling social time so a client has recovery time before and after.', 'Use it to help a client pace social events.', array['Adults', 'Teens']::text[], '20 minutes', 'Look at the client''s week and plan which events matter most. Add recovery time after. Avoid using it to cut out all social contact. Tie events to what the client values.', '[{"id": "f0", "type": "textarea", "label": "Social events this week"}, {"id": "f1", "type": "textarea", "label": "Which ones matter most to me"}, {"id": "f2", "type": "textarea", "label": "How I will recover"}, {"id": "f3", "type": "textarea", "label": "What I will do to prepare"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels like too much"}]'::jsonb, array['social anxiety', 'planning', 'energy']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('spotlight-reality-check', 'Spotlight Reality Check', 'cbt'::resource_kind, 'An experiment for comparing how much a client thinks others notice them with what happens.', 'Use it to test the spotlight effect.', array['Adults', 'Teens']::text[], '25 minutes', 'Predict how much others will notice a small slip and then run it. Gather reports from a friend or from observations. Compare. The result informs what the client believes. Debrief what was learned.', '[{"id": "f0", "type": "textarea", "label": "What I think others will notice"}, {"id": "f1", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I tried"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I make of it"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('showing-up-anyway-practice', 'Showing Up Anyway Practice', 'act'::resource_kind, 'A practice for choosing a social action that fits a value while anxiety is present.', 'Use it to link social steps to what matters.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what the client would want from social life if anxiety were less in charge. Choose a step and agree to bring anxiety along. Check in on what the experience was like.', '[{"id": "f0", "type": "textarea", "label": "What I want from my social life"}, {"id": "f1", "type": "textarea", "label": "A step that fits"}, {"id": "f2", "type": "textarea", "label": "What anxiety says about it"}, {"id": "f3", "type": "textarea", "label": "What I will do while it is there"}, {"id": "f4", "type": "textarea", "label": "How I will know I did it"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('social-event-teamwork-plan', 'Social Event Teamwork Plan', 'couples'::resource_kind, 'A plan for how partners work as a team at social events.', 'Use it to give a socially anxious partner a supportive plan.', array['Couples']::text[], '25 minutes', 'Ask the more anxious partner what helps and what to avoid, such as being pushed or left alone. Plan a signal for a break and a time to leave. Review afterward and adjust. Respect both partners'' needs.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me at events"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I can help"}, {"id": "f2", "type": "textarea", "label": "A signal for a break"}, {"id": "f3", "type": "textarea", "label": "When we will leave"}, {"id": "f4", "type": "textarea", "label": "How we will debrief"}]'::jsonb, array['social anxiety', 'couples', 'support']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('brave-conversation-spinner-game', 'Brave Conversation Spinner Game', 'kids'::resource_kind, 'A child spins a spinner for a conversation challenge and practices it with a parent.', 'Use it to make small social risks playful for a child.', array['Children']::text[], '20 minutes', 'Make a spinner with challenges like say hello, ask a question or share a favorite. The child spins and the parent plays the other person. Cheer attempts and never speak for the child. Move to real small tries later. Ask the child which spin felt easiest and which felt hardest.', '[{"id": "f0", "type": "textarea", "label": "The challenge I spun"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "How it felt in my body"}, {"id": "f3", "type": "textarea", "label": "The spin that was hardest"}, {"id": "f4", "type": "textarea", "label": "Who I could try one with this week"}]'::jsonb, array['social anxiety', 'children', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('grief-memory-collection-sheet', 'Grief Memory Collection Sheet', 'worksheet'::resource_kind, 'A sheet for collecting small memories and details of someone who has died.', 'Use it to help a client keep the person close in a gentle way.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite memories of everyday things, such as a laugh or a saying. Let the client set the pace and stop when needed. Some memories may bring tears, which is normal. Offer ways to keep the memories.', '[{"id": "f0", "type": "textarea", "label": "A small thing I remember about them"}, {"id": "f1", "type": "textarea", "label": "A saying or sound I connect to them"}, {"id": "f2", "type": "textarea", "label": "Something they taught me"}, {"id": "f3", "type": "textarea", "label": "A place I feel close to them"}, {"id": "f4", "type": "textarea", "label": "How I want to keep this memory"}]'::jsonb, array['grief and loss', 'memory', 'narrative']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('grief-thought-check-sheet', 'Grief Thought Check Sheet', 'cbt'::resource_kind, 'A thought record for should-have thoughts after a loss.', 'Use it to look at guilt and what-if thoughts after a death.', array['Adults']::text[], '20 minutes', 'Notice the what-ifs and ask what the client knew then. Hindsight changes the picture. Not every thought should be challenged; some express love. Go gently. The client decides which thoughts to look at.', '[{"id": "f0", "type": "textarea", "label": "A should-have thought"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "What the thought says about how much I cared"}, {"id": "f4", "type": "textarea", "label": "What I want to do with it"}]'::jsonb, array['grief and loss', 'thinking traps', 'guilt']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('carrying-love-and-loss-practice', 'Carrying Love and Loss Practice', 'act'::resource_kind, 'A practice for making room for sorrow while turning toward what the loved person valued.', 'Use it to hold grief and love together.', array['Adults']::text[], '20 minutes', 'Ask what the person cared about and how the client could honor it. Allow sadness to be present. Avoid hurrying the grief. Pick a small act the client can do this week.', '[{"id": "f0", "type": "textarea", "label": "Something I miss most"}, {"id": "f1", "type": "textarea", "label": "A value they lived by"}, {"id": "f2", "type": "textarea", "label": "A way I could honor it"}, {"id": "f3", "type": "textarea", "label": "What sadness feels like in my body"}, {"id": "f4", "type": "textarea", "label": "What I will do this week"}]'::jsonb, array['grief and loss', 'acceptance', 'values']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('anniversary-cope-ahead-plan', 'Anniversary Cope Ahead Plan', 'dbt'::resource_kind, 'A plan for getting through birthdays, holidays and anniversaries.', 'Use it to prepare for hard dates.', array['Adults']::text[], '25 minutes', 'Pick a date and plan how the client wants to spend it, who they want with them and what skills they will use. Include a back-up plan. Review afterward. Expect that feelings vary. Keep the plan flexible.', '[{"id": "f0", "type": "textarea", "label": "The date I am preparing for"}, {"id": "f1", "type": "textarea", "label": "How I would like to spend it"}, {"id": "f2", "type": "textarea", "label": "Who I want near"}, {"id": "f3", "type": "textarea", "label": "Skills I will use"}, {"id": "f4", "type": "textarea", "label": "A back-up plan if it feels like too much"}]'::jsonb, array['grief and loss', 'cope ahead', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('remembering-together-scrapbook', 'Remembering Together Scrapbook', 'kids'::resource_kind, 'A child and parent make a small scrapbook of pictures and stories about someone who died.', 'Use it to give a child a safe way to remember.', array['Children']::text[], '30 minutes', 'The child chooses pictures and draws. The parent listens, shares their own memories and answers questions honestly in simple words. Let the child lead and stop when they want. Keep it somewhere easy to reach.', '[{"id": "f0", "type": "textarea", "label": "My favorite memory of them"}, {"id": "f1", "type": "textarea", "label": "Something they liked"}, {"id": "f2", "type": "textarea", "label": "Something I wish I could tell them"}, {"id": "f3", "type": "textarea", "label": "How I feel today"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to about them"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('needs-and-requests-sheet', 'Needs and Requests Sheet', 'worksheet'::resource_kind, 'A sheet for turning a complaint into a need and a clear, doable request.', 'Use it to help a client ask for what they want.', array['Adults']::text[], '25 minutes', 'Take a complaint and ask what need sits beneath it. Then turn the need into a specific request. Role play it. Remind the client that the other person may say no. Revise until the request is clear.', '[{"id": "f0", "type": "textarea", "label": "My complaint"}, {"id": "f1", "type": "textarea", "label": "The need underneath it"}, {"id": "f2", "type": "textarea", "label": "A specific request"}, {"id": "f3", "type": "textarea", "label": "How I will ask"}, {"id": "f4", "type": "textarea", "label": "What I will do if the answer is no"}]'::jsonb, array['relationship issues', 'needs', 'communication']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('relationship-assumption-check', 'Relationship Assumption Check', 'cbt'::resource_kind, 'A thought record for assumptions about what a partner or friend means.', 'Use it to catch mind reading in close relationships.', array['Adults']::text[], '20 minutes', 'Choose a recent exchange and write the assumption. Ask what else it could mean and how the client could check. Practice asking a question. Notice patterns across relationships.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I assumed"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "How I could check"}, {"id": "f4", "type": "textarea", "label": "What I will say or do"}]'::jsonb, array['relationship issues', 'thinking traps', 'core CBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('daily-connection-rituals-sheet', 'Daily Connection Rituals Sheet', 'couples'::resource_kind, 'A sheet for choosing a few small daily rituals that keep partners connected.', 'Use it to build everyday connection.', array['Couples']::text[], '25 minutes', 'Each partner suggests rituals, like a morning hug or a goodbye kiss, and the couple picks two to start. Keep them small. Review after a week. They work by being regular, not long.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rituals I would like"}, {"id": "f1", "type": "textarea", "label": "Partner B: rituals I would like"}, {"id": "f2", "type": "textarea", "label": "The two we chose"}, {"id": "f3", "type": "textarea", "label": "When each will happen"}, {"id": "f4", "type": "textarea", "label": "How we will remind each other"}]'::jsonb, array['relationship issues', 'rituals', 'connection']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('relationship-mindfulness-practice', 'Relationship Mindfulness Practice', 'dbt'::resource_kind, 'A practice for being fully present with a loved one for a few minutes.', 'Use it to bring attention and warmth to everyday contact.', array['Adults']::text[], '20 minutes', 'Pick a short window, ten minutes, with no phones. Practice listening and noticing. Debrief what was different. Encourage one or two tries per week. Keep expectations low.', '[{"id": "f0", "type": "textarea", "label": "When I tried it"}, {"id": "f1", "type": "textarea", "label": "What I noticed about the other person"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention"}, {"id": "f3", "type": "textarea", "label": "How it felt"}, {"id": "f4", "type": "textarea", "label": "When I will try again"}]'::jsonb, array['relationship issues', 'mindfulness', 'GIVE']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('relationship-tic-tac-talk', 'Relationship Tic-Tac-Talk', 'game'::resource_kind, 'A tic-tac-toe game where each square holds a communication prompt answered before placing a mark.', 'Use it to practice talking about relationships in a light way.', array['Groups']::text[], '25 minutes', 'Fill the grid with prompts such as describe a time you felt heard. Players answer before marking. Keep prompts low stakes. Debrief what was easy and hard to say.', '[{"id": "f0", "type": "textarea", "label": "The prompt I answered"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What I learned from a partner''s answer"}, {"id": "f3", "type": "textarea", "label": "A prompt that was hard"}, {"id": "f4", "type": "textarea", "label": "What I will try with someone I care about"}]'::jsonb, array['relationship issues', 'communication', 'group']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('support-circle-map', 'Support Circle Map', 'worksheet'::resource_kind, 'A map of people and places that offer safety and support, ranked by how safe they feel.', 'Use it to help a client notice who and what is on their side.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep it entirely about the present. Never ask for details of what happened. Let the client place people closer or further and revisit often. Also include places, pets, routines and professionals. If a minor discloses, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to me"}, {"id": "f1", "type": "textarea", "label": "Places that feel safe"}, {"id": "f2", "type": "textarea", "label": "A routine that helps me feel steady"}, {"id": "f3", "type": "textarea", "label": "Someone I want to feel closer to"}, {"id": "f4", "type": "textarea", "label": "Someone I will contact this week"}]'::jsonb, array['sexual abuse', 'support', 'safety']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('self-blame-gentle-reframe', 'Self-Blame Gentle Reframe', 'cbt'::resource_kind, 'A gentle sheet for noticing self-blame thoughts and offering a kinder, fairer view.', 'Use it to ease self-blame without revisiting events.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the work on current thoughts and never ask for details. Use language that places responsibility with the person who caused harm. Go at the client''s pace and stop if it is too much. The client chooses the words that feel true.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought I have"}, {"id": "f1", "type": "textarea", "label": "Where I think it came from"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer way to see it"}, {"id": "f4", "type": "textarea", "label": "Who can support me with this"}]'::jsonb, array['sexual abuse', 'self-blame', 'shame']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('safe-body-connection-practice', 'Safe Body Connection Practice', 'act'::resource_kind, 'A brief practice for noticing safe, neutral parts of the body and the present moment.', 'Use it to rebuild a sense of safety in the body at the client''s pace.', array['Adults']::text[], '15 minutes', 'Offer choices at every step and make clear that the client can stop at any time. Start with outside of the body, like feet on the floor. Never push. Debrief what felt okay. Stay with the present.', '[{"id": "f0", "type": "textarea", "label": "A part of my body that feels neutral or okay"}, {"id": "f1", "type": "textarea", "label": "What I notice in my feet"}, {"id": "f2", "type": "textarea", "label": "What I see in the room"}, {"id": "f3", "type": "textarea", "label": "What I want to do if it feels like too much"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['sexual abuse', 'grounding', 'acceptance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('safety-skills-menu', 'Safety Skills Menu', 'dbt'::resource_kind, 'A menu of calming and safety skills for hard moments.', 'Use it to give a client choices for feeling steadier.', array['Adults', 'Teens']::text[], '20 minutes', 'Build it from what the client already uses and add one or two new ones. Practice a couple in session. Include people to call and, if the client is at risk, call or text 988. Keep the focus on present safety.', '[{"id": "f0", "type": "textarea", "label": "Skills that help me feel steady"}, {"id": "f1", "type": "textarea", "label": "A person to contact"}, {"id": "f2", "type": "textarea", "label": "A place I can go"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself"}, {"id": "f4", "type": "textarea", "label": "If I am in crisis, I can call or text 988"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'coping skills']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('safe-adults-hand-drawing', 'Safe Adults Hand Drawing', 'kids'::resource_kind, 'A child traces a hand and writes a trusted grown-up on each finger, as a plan for who to tell if something feels wrong.', 'Use it to help a child name safe people they can go to.', array['Children']::text[], '25 minutes', 'The child traces their hand and writes names. The parent helps pick adults the child can reach. Say clearly that the child can tell and will be believed. Clinicians should remember their reporting duties if a child discloses, and avoid asking leading questions.', '[{"id": "f0", "type": "textarea", "label": "The first safe grown-up"}, {"id": "f1", "type": "textarea", "label": "The second safe grown-up"}, {"id": "f2", "type": "textarea", "label": "The third safe grown-up"}, {"id": "f3", "type": "textarea", "label": "What I will say if something feels wrong"}, {"id": "f4", "type": "textarea", "label": "Where I keep this drawing"}]'::jsonb, array['sexual abuse', 'children', 'body safety']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('coping-strategy-test-drive-sheet', 'Coping Strategy Test Drive Sheet', 'worksheet'::resource_kind, 'A sheet for trying a coping strategy as an experiment and rating what it does.', 'Use it to find which skills actually help.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one skill and a situation and rate distress before and after. Record what was hard about using it. Expect some to fail, which is useful information. Choose what to try next together.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried"}, {"id": "f1", "type": "textarea", "label": "The situation"}, {"id": "f2", "type": "textarea", "label": "How I felt before and after"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['coping skills', 'experiments', 'self-monitoring']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('coping-thought-rehearsal-card', 'Coping Thought Rehearsal Card', 'cbt'::resource_kind, 'A card with coping thoughts for a hard situation that a client rehearses aloud.', 'Use it to prepare self-talk before it is needed.', array['Adults', 'Teens']::text[], '15 minutes', 'Write coping statements in the client''s own voice and rehearse them. Test them against a recent hard moment. Edit anything that sounds fake. Put the card where the client can see it.', '[{"id": "f0", "type": "textarea", "label": "The hard situation"}, {"id": "f1", "type": "textarea", "label": "A coping thought that feels true"}, {"id": "f2", "type": "textarea", "label": "Another that feels useful"}, {"id": "f3", "type": "textarea", "label": "When I will read the card"}, {"id": "f4", "type": "textarea", "label": "What I will do afterward"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('skill-willingness-check', 'Skill Willingness Check', 'act'::resource_kind, 'A check on whether the client is willing to use a skill even when it feels uncomfortable.', 'Use it to help a client use skills with discomfort present.', array['Adults']::text[], '15 minutes', 'Ask where on a scale the client is willing to try a skill. If low, explore what is in the way. A small willingness is enough. Notice avoidance disguised as coping.', '[{"id": "f0", "type": "textarea", "label": "A skill I know but do not use"}, {"id": "f1", "type": "textarea", "label": "How willing I am, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What is in the way"}, {"id": "f3", "type": "textarea", "label": "What would help me try"}, {"id": "f4", "type": "textarea", "label": "When I will try it"}]'::jsonb, array['coping skills', 'willingness', 'workability']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-menu-builder', 'Distress Tolerance Menu Builder', 'dbt'::resource_kind, 'A menu builder for crisis survival skills sorted by situation and intensity.', 'Use it to give a client options for different moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort skills into groups for low, medium and high intensity. Choose one or two for each. Practice them. Revise after use. Keep it handy, such as in a phone note.', '[{"id": "f0", "type": "textarea", "label": "Skills for low intensity"}, {"id": "f1", "type": "textarea", "label": "Skills for medium intensity"}, {"id": "f2", "type": "textarea", "label": "Skills for high intensity"}, {"id": "f3", "type": "textarea", "label": "A skill I want to learn"}, {"id": "f4", "type": "textarea", "label": "Where I keep this menu"}]'::jsonb, array['coping skills', 'distress tolerance', 'planning']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('coping-skill-charades-relay', 'Coping Skill Charades Relay', 'game'::resource_kind, 'A relay in which teams act out coping skills and race to name them.', 'Use it to refresh coping skills in a lively way.', array['Groups']::text[], '25 minutes', 'Teams line up and take turns acting out skill cards without speaking. Guessers name the skill and say a time they used it. Keep scoring light. Debrief which skills people forgot and which they want to try.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted or guessed"}, {"id": "f1", "type": "textarea", "label": "A time I used it"}, {"id": "f2", "type": "textarea", "label": "A skill I forgot"}, {"id": "f3", "type": "textarea", "label": "A skill I want to try"}, {"id": "f4", "type": "textarea", "label": "What I will remember from today"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('fear-facts-sheet', 'Fear Facts Sheet', 'worksheet'::resource_kind, 'A fact sheet a client fills in about their fear: what they know, what they assume and what they could find out.', 'Use it to separate facts from guesses about a feared thing.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client what they know about the feared thing and what they assume. Help them check facts together. Do not argue with the fear. Plan a safe way to gather more information.', '[{"id": "f0", "type": "textarea", "label": "The thing I fear"}, {"id": "f1", "type": "textarea", "label": "What I know for sure"}, {"id": "f2", "type": "textarea", "label": "What I assume"}, {"id": "f3", "type": "textarea", "label": "How I could find out more"}, {"id": "f4", "type": "textarea", "label": "What I notice in my body when I think of it"}]'::jsonb, array['phobias', 'psychoeducation', 'anxiety']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('feared-outcome-probability-check', 'Feared Outcome Probability Check', 'cbt'::resource_kind, 'A check for the predicted outcome of facing a fear, with space for what actually occurred.', 'Use it to compare predictions with what happens.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the predicted outcome and how sure the client is. Facing it gradually, then record what happened. Discuss the differences. A prediction that came true is information as well. Plan a next step.', '[{"id": "f0", "type": "textarea", "label": "The feared outcome"}, {"id": "f1", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('fear-and-freedom-practice', 'Fear and Freedom Practice', 'act'::resource_kind, 'A practice for naming what a fear keeps out of a client''s life and one step they are willing to take.', 'Use it to link exposure steps to something meaningful.', array['Adults']::text[], '20 minutes', 'Ask what the client would be doing if the fear were quieter. Choose a small step toward it and agree to bring the fear along. Debrief afterward.', '[{"id": "f0", "type": "textarea", "label": "What fear has kept me from"}, {"id": "f1", "type": "textarea", "label": "What I would like to be doing"}, {"id": "f2", "type": "textarea", "label": "A small step I am willing to take"}, {"id": "f3", "type": "textarea", "label": "What the fear says"}, {"id": "f4", "type": "textarea", "label": "What I will do with it"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('exposure-day-skills-plan', 'Exposure Day Skills Plan', 'dbt'::resource_kind, 'A plan of skills to use before, during and after a practice step.', 'Use it to help a client stay with an exposure step.', array['Adults']::text[], '20 minutes', 'Plan skills for each stage. Remind the client the point is to stay with the step, not to eliminate fear. Practice breathing and grounding. Debrief afterward and celebrate the attempt.', '[{"id": "f0", "type": "textarea", "label": "Today''s step"}, {"id": "f1", "type": "textarea", "label": "A skill I will use beforehand"}, {"id": "f2", "type": "textarea", "label": "A skill I will use during"}, {"id": "f3", "type": "textarea", "label": "How I will reward myself after"}, {"id": "f4", "type": "textarea", "label": "What I will review"}]'::jsonb, array['phobias', 'exposure', 'distress tolerance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('fear-fighter-superhero-craft', 'Fear Fighter Superhero Craft', 'kids'::resource_kind, 'A child designs a superhero costume piece and picks a small brave step to take.', 'Use it to make facing small fears playful.', array['Children']::text[], '30 minutes', 'The child decorates a cape or badge and names a power. They choose a tiny brave step with the parent''s help. The parent cheers on, never forces and stays near. Repeat with bigger steps later.', '[{"id": "f0", "type": "textarea", "label": "My superhero name"}, {"id": "f1", "type": "textarea", "label": "My power"}, {"id": "f2", "type": "textarea", "label": "The fear I am facing"}, {"id": "f3", "type": "textarea", "label": "My first small brave step"}, {"id": "f4", "type": "textarea", "label": "How my parent will help"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('body-appreciation-letter-sheet', 'Body Appreciation Letter Sheet', 'worksheet'::resource_kind, 'A letter of thanks to the body for what it does and has carried the client through.', 'Use it to focus on what the body does rather than how it looks.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to write to their body with thanks. Keep the focus on abilities and experiences. Avoid any talk of size or measurement. Notice discomfort and slow down. Optional to read aloud.', '[{"id": "f0", "type": "textarea", "label": "Something my body helps me do"}, {"id": "f1", "type": "textarea", "label": "A time it carried me through"}, {"id": "f2", "type": "textarea", "label": "Something I want to say to it"}, {"id": "f3", "type": "textarea", "label": "What I want to do to care for it"}, {"id": "f4", "type": "textarea", "label": "How writing this felt"}]'::jsonb, array['body image', 'gratitude', 'self-compassion']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('appearance-comparison-thought-check', 'Appearance Comparison Thought Check', 'cbt'::resource_kind, 'A thought record for thoughts that compare appearance with others.', 'Use it to loosen comparison thoughts.', array['Adults', 'Teens']::text[], '20 minutes', 'Look at what the comparison says and where the standard comes from. Ask what is left out of the picture. Move attention toward values. Keep it away from any measuring of the body.', '[{"id": "f0", "type": "textarea", "label": "The comparison I made"}, {"id": "f1", "type": "textarea", "label": "What I told myself"}, {"id": "f2", "type": "textarea", "label": "Where this standard came from"}, {"id": "f3", "type": "textarea", "label": "What is missing from the picture"}, {"id": "f4", "type": "textarea", "label": "What I would rather focus on"}]'::jsonb, array['body image', 'social comparison', 'thought challenging']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('values-beyond-the-mirror-practice', 'Values Beyond the Mirror Practice', 'act'::resource_kind, 'A practice for acting on what matters when appearance thoughts are loud.', 'Use it to take values-based actions while thoughts about looks are present.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what the client has been holding back from because of appearance thoughts. Choose a small step and agree to bring the thoughts along. Debrief on what the experience was.', '[{"id": "f0", "type": "textarea", "label": "Something I put off because of how I look"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "A small step I will take"}, {"id": "f3", "type": "textarea", "label": "What my mind says about it"}, {"id": "f4", "type": "textarea", "label": "What I do while it chatters"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('body-neutral-mindfulness-card', 'Body Neutral Mindfulness Card', 'dbt'::resource_kind, 'A card for describing the body in neutral, factual words during mindfulness.', 'Use it to move from judgment toward neutral description.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach describing sensations and functions in neutral words, such as strong legs or warm hands. Practice a short scan. Avoid any evaluation of shape or size. Review what felt possible.', '[{"id": "f0", "type": "textarea", "label": "A neutral word for my body today"}, {"id": "f1", "type": "textarea", "label": "Something it did today"}, {"id": "f2", "type": "textarea", "label": "How I noticed the judgment voice"}, {"id": "f3", "type": "textarea", "label": "What I did when it came"}, {"id": "f4", "type": "textarea", "label": "How I will practice again"}]'::jsonb, array['body image', 'mindfulness', 'acceptance']::text[], '2026-10-06T15:00:00+00:00'::timestamptz),
  ('body-superpowers-poster', 'Body Superpowers Poster', 'kids'::resource_kind, 'A child draws or collages the things their body can do and displays it as a poster.', 'Use it to celebrate what the body can do.', array['Children']::text[], '30 minutes', 'The child draws or cuts pictures of their favorite movements and abilities. The parent talks about what bodies do and avoids appearance comments. Hang the poster in the child''s room.', '[{"id": "f0", "type": "textarea", "label": "A power my body has"}, {"id": "f1", "type": "textarea", "label": "Another thing my body can do"}, {"id": "f2", "type": "textarea", "label": "A way my body helps my friends"}, {"id": "f3", "type": "textarea", "label": "How I take care of my body"}, {"id": "f4", "type": "textarea", "label": "What I will add next"}]'::jsonb, array['body image', 'children', 'art']::text[], '2026-10-06T15:00:00+00:00'::timestamptz)
